# Next.js Middleware & Routing with RBAC

**Version:** 1.0
**Purpose:** Enforce permissions at the routing layer before any component renders

## Part 1: Middleware Setup

**File: `middleware.ts` (root)**

```typescript
import { NextRequest, NextResponse } from "next/server";
import { verifySession } from "@/lib/auth";

export async function middleware(request: NextRequest) {
  const { pathname, hostname } = request.nextUrl;

  // Extract subdomain
  const host = hostname.split(":")[0]; // Remove port if present
  const parts = host.split(".");
  let subdomain = "app";
  let product = "edumyles"; // Default

  if (parts.length >= 3) {
    // Format: [subdomain].[product].localhost or [subdomain].[product].com
    subdomain = parts[0];
    product = parts[1];
  } else if (parts.length === 2) {
    // Format: [product].localhost or localhost:3000
    product = parts[0];
  }

  // Public routes (no auth required)
  const publicRoutes = [
    "/auth/login",
    "/auth/signup",
    "/auth/error",
    "/auth/callback",
    "/auth/logout",
    "/",
    "/pricing",
    "/features",
    "/contact",
    "/security",
    "/privacy",
    "/terms",
    "/cookies",
    "/status",
    "/maintenance",
  ];

  if (publicRoutes.some(route => pathname.startsWith(route))) {
    return NextResponse.next();
  }

  // Verify session
  const session = request.cookies.get(`__${product}_session`);

  if (!session) {
    return NextResponse.redirect(new URL("/auth/login", request.url));
  }

  // Verify user and role
  let user;
  try {
    user = await verifySession(session.value, product);
  } catch (error) {
    // Invalid session
    const response = NextResponse.redirect(new URL("/auth/login", request.url));

    // Clear cookies on invalid session
    response.cookies.set(`__${product}_session`, "", {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 0,
    });

    return response;
  }

  if (!user) {
    return NextResponse.redirect(new URL("/auth/login", request.url));
  }

  // RBAC: Validate access to route based on subdomain and role
  const isAuthorized = validateAccess(subdomain, pathname, user);

  if (!isAuthorized) {
    return NextResponse.redirect(new URL("/unauthorized", request.url));
  }

  // Attach user to request for use in components
  const requestWithUser = NextResponse.next();
  requestWithUser.headers.set("x-user-id", user.id);
  requestWithUser.headers.set("x-user-role", user.role);
  requestWithUser.headers.set("x-user-org", user.organizationId || "");

  return requestWithUser;
}

// RBAC validation function
function validateAccess(
  subdomain: string,
  pathname: string,
  user: { id: string; role: string; organizationId?: string }
): boolean {
  // Master Admin panel (/platform)
  if (subdomain === "admin") {
    if (pathname.startsWith("/platform")) {
      return user.role === "platform_admin";
    }
  }

  // Super Admin panel (/admin)
  if (subdomain === "network") {
    if (pathname.startsWith("/admin")) {
      const allowedRoles = [
        "network_operator",
        "operator_manager",
        "agency_super_admin",
        "reseller_super_admin",
        "platform_admin",
      ];
      return allowedRoles.includes(user.role);
    }
  }

  // Agency panel (/agency)
  if (subdomain === "agency") {
    if (pathname.startsWith("/agency")) {
      return (
        user.role === "agency_super_admin" ||
        user.role === "platform_admin"
      );
    }
  }

  // Reseller panel (/reseller)
  if (subdomain === "reseller") {
    if (pathname.startsWith("/reseller")) {
      return (
        user.role === "reseller_super_admin" ||
        user.role === "platform_admin"
      );
    }
  }

  // Partner panel (/partner)
  if (subdomain === "partner") {
    if (pathname.startsWith("/partner")) {
      return (
        user.role === "partner_admin" ||
        user.role === "platform_admin"
      );
    }
  }

  // Tenant subdomain ([client].[product].com)
  // This is the client portal (/dashboard)
  if (subdomain !== "admin" && subdomain !== "network" &&
      subdomain !== "agency" && subdomain !== "reseller" &&
      subdomain !== "partner") {
    if (pathname.startsWith("/dashboard")) {
      // User must belong to this organization
      return !!user.organizationId;
    }
  }

  return true;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    "/((?!api|_next/static|_next/image|favicon.ico).*)",
  ],
};
```

## Part 2: Auth Library

**File: `lib/auth.ts`**

```typescript
import { cookies } from "next/headers";
import { jwtVerify } from "jose";

const JWT_SECRET = new TextEncoder().encode(
  process.env.JWT_SECRET || "your-secret-key"
);

export interface AuthUser {
  id: string;
  email: string;
  name?: string;
  role: string;
  organizationId?: string;
  agencyId?: string;
  networkId?: string;
  product: string;
  iat: number;
  exp: number;
}

/**
 * Verify session token and return user
 */
export async function verifySession(
  token: string,
  product: string
): Promise<AuthUser | null> {
  try {
    const verified = await jwtVerify(token, JWT_SECRET);
    const payload = verified.payload as any;

    // Check expiration
    if (payload.exp && Date.now() / 1000 > payload.exp) {
      return null; // Expired
    }

    return {
      id: payload.sub,
      email: payload.email,
      name: payload.name,
      role: payload.role,
      organizationId: payload.organizationId,
      agencyId: payload.agencyId,
      networkId: payload.networkId,
      product,
      iat: payload.iat,
      exp: payload.exp,
    };
  } catch (error) {
    console.error("Session verification failed:", error);
    return null;
  }
}

/**
 * Get current authenticated user from cookies
 */
export async function getCurrentUser(product: string): Promise<AuthUser | null> {
  const cookieStore = cookies();
  const sessionCookie = cookieStore.get(`__${product}_session`);

  if (!sessionCookie) {
    return null;
  }

  return verifySession(sessionCookie.value, product);
}

/**
 * Clear auth cookies (on logout)
 */
export async function clearAuthCookies(product: string) {
  const cookieStore = cookies();

  const cookiesToClear = [
    `__${product}_session`,
    `__${product}_tenant`,
    `__${product}_csrf`,
  ];

  cookiesToClear.forEach(name => {
    cookieStore.set(name, "", {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 0,
      expires: new Date(0),
    });
  });
}

/**
 * Require authentication in server components
 */
export async function requireAuth(product: string): Promise<AuthUser> {
  const user = await getCurrentUser(product);

  if (!user) {
    throw new Error("Unauthenticated");
  }

  return user;
}

/**
 * Require specific role in server components
 */
export async function requireRole(
  product: string,
  allowedRoles: string[]
): Promise<AuthUser> {
  const user = await requireAuth(product);

  if (!allowedRoles.includes(user.role)) {
    throw new Error(`Unauthorized: required role ${allowedRoles.join(" or ")}`);
  }

  return user;
}

/**
 * Require organization ownership in server components
 */
export async function requireTenant(
  product: string,
  organizationId: string
): Promise<AuthUser> {
  const user = await requireAuth(product);

  if (user.role !== "platform_admin" && user.organizationId !== organizationId) {
    throw new Error("Access denied: not member of this organization");
  }

  return user;
}
```

