export async function RouteGuard({
  children,
  requiredRole,
  requiredProduct = "edumyles", // Default product
}: RouteGuardProps) {
  const user = await getCurrentUser(requiredProduct);

  // Check authentication
  if (!user) {
    redirect("/auth/login");
  }

  // Check authorization
  if (requiredRole && !requiredRole.includes(user.role)) {
    redirect("/unauthorized");
  }

  return <>{children}</>;
}

