## Part 4: Redirect Logic

**File: `app/auth/callback/route.ts`**

```typescript
import { NextRequest, NextResponse } from "next/server";
import { workos } from "@/lib/workos";

export async function GET(request: NextRequest) {
  const code = request.nextUrl.searchParams.get("code");

  if (!code) {
    return NextResponse.redirect(new URL("/auth/error", request.url));
  }

  try {
    // Exchange code for session
    const session = await workos.userManagement.authenticateWithCode({
      code,
      clientId: process.env.WORKOS_CLIENT_ID!,
    });

    const user = session.user;

    // Get user's roles from WorkOS
    // Determine primary product and role
    const product = determineProduct(request.url);
    const role = determineRole(user, product);

    if (!role) {
      return NextResponse.redirect(new URL("/auth/pending", request.url));
    }

    // Create session cookie
    const response = NextResponse.redirect(
      new URL(getRedirectPath(role, product), request.url)
    );

    response.cookies.set(`__${product}_session`, session.sessionToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 24 * 60 * 60, // 24 hours
    });

    return response;
  } catch (error) {
    console.error("Auth callback error:", error);
    return NextResponse.redirect(new URL("/auth/error", request.url));
  }
}

/**
 * Determine redirect path based on role
 */
function getRedirectPath(role: string, product: string): string {
  // RBAC redirect rules
  const redirectMap: Record<string, string> = {
    platform_admin: "/platform/dashboard",
    operator_manager: "/admin/dashboard",
    network_operator: "/admin/organizations",
    agency_super_admin: "/agency/clients",
    reseller_super_admin: "/reseller/clients",
    partner_admin: "/partner/integrations",
    client_admin: "/dashboard",

    // Product-specific roles
    teacher: "/dashboard/academics",
    student: "/dashboard/assignments",
    parent: "/dashboard/children",
    principal: "/dashboard",
  };

  return redirectMap[role] || "/dashboard";
}

/**
 * Determine product from referrer
 */
function determineProduct(url: string): string {
  // Extract from URL
  // e.g., https://admin.edumyles.com → edumyles
  const match = url.match(/\.(\w+)(\.com|\.localhost)/);
  return match ? match[1] : "edumyles";
}

/**
 * Determine role from WorkOS user organizations
 */
function determineRole(user: any, product: string): string | null {
  // Check WorkOS user for role in this product
  const org = user.primaryOrganization;

  // WorkOS stores role as metadata
  return org?.metadata?.[`${product}_role`] || null;
}
