## Part 6: Session Timeout Handler

**File: `lib/session-timeout.ts`**

```typescript
/**
 * Session timeout configuration per role
 */
export const SESSION_TIMEOUTS = {
  platform_admin: 30 * 60, // 30 minutes
  network_operator: 60 * 60, // 1 hour
  operator_manager: 60 * 60, // 1 hour
  agency_super_admin: 2 * 60 * 60, // 2 hours
  reseller_super_admin: 2 * 60 * 60, // 2 hours
  client_admin: 2 * 60 * 60, // 2 hours
  default: 2 * 60 * 60, // 2 hours
};

/**
 * Warning threshold (show warning this many seconds before timeout)
 */
export const SESSION_WARNING_THRESHOLD = 5 * 60; // 5 minutes

/**
 * Hook to manage session timeout in React
 */
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

export function useSessionTimeout(user: any) {
  const router = useRouter();
  const [showWarning, setShowWarning] = useState(false);

  useEffect(() => {
    const timeout = SESSION_TIMEOUTS[user?.role] || SESSION_TIMEOUTS.default;
    const warningTime = timeout - SESSION_WARNING_THRESHOLD;

    let warningTimer: NodeJS.Timeout;
    let timeoutTimer: NodeJS.Timeout;

    const resetTimers = () => {
      clearTimeout(warningTimer);
      clearTimeout(timeoutTimer);
      setShowWarning(false);

      // Show warning
      warningTimer = setTimeout(() => {
        setShowWarning(true);
      }, warningTime * 1000);

      // Actual timeout
      timeoutTimer = setTimeout(() => {
        clearSession();
      }, timeout * 1000);
    };

    const clearSession = async () => {
      // Clear cookies
      await fetch("/api/auth/logout", { method: "POST" });

      // Redirect to login
      router.push("/auth/login?reason=timeout");
    };

    // Track activity
    const events = ["mousedown", "keydown", "scroll", "touchstart"];

    events.forEach(event => {
      document.addEventListener(event, resetTimers, true);
    });

    // Initialize timers
    resetTimers();

    return () => {
      events.forEach(event => {
        document.removeEventListener(event, resetTimers, true);
      });
      clearTimeout(warningTimer);
      clearTimeout(timeoutTimer);
    };
  }, [user, router]);

  return { showWarning };
}
```

## Part 7: CSRF Protection

**File: `lib/csrf.ts`**

```typescript
import crypto from "crypto";
import { cookies } from "next/headers";

const CSRF_SECRET = process.env.CSRF_SECRET || "csrf-secret";

/**
 * Generate CSRF token
 */
export function generateCsrfToken(): string {
  return crypto.randomBytes(32).toString("hex");
}

/**
 * Verify CSRF token
 */
export function verifyCsrfToken(token: string, expected: string): boolean {
  return crypto.timingSafeEqual(
    Buffer.from(token),
    Buffer.from(expected)
  );
}

/**
 * Set CSRF cookie (HttpOnly)
 */
export function setCsrfToken(product: string) {
  const token = generateCsrfToken();
  const cookieStore = cookies();

  cookieStore.set(`__${product}_csrf`, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60, // 1 hour
  });

  return token;
}

/**
 * Get CSRF token from cookie
 */
export function getCsrfToken(product: string): string | null {
  const cookieStore = cookies();
  return cookieStore.get(`__${product}_csrf`)?.value || null;
}

/**
 * API route protection with CSRF
 */
export async function validateCsrfToken(
  request: Request,
  product: string
): Promise<boolean> {
  const csrfToken = request.headers.get("x-csrf-token");
  const cookieToken = getCsrfToken(product);

  if (!csrfToken || !cookieToken) {
    return false;
  }

  try {
    return verifyCsrfToken(csrfToken, cookieToken);
  } catch {
    return false;
  }
}
```

**Usage in API routes:**
```typescript
export async function POST(request: Request) {
  const product = "edumyles";

  // Validate CSRF
  const csrfValid = await validateCsrfToken(request, product);
  if (!csrfValid) {
    return Response.json({ error: "Invalid CSRF token" }, { status: 403 });
  }

  // Process mutation
