## Part 3: Assigning Role to User (Programmatic)

```typescript
// lib/workos-roles.ts
import { WorkOS } from "@workos-inc/node";

const workos = new WorkOS(process.env.WORKOS_API_KEY!);

/**
 * Assign a role to a user within a specific organization
 */
export async function assignUserRole(
  userId: string,
  organizationId: string,
  roleSlug: string
) {
  // Create organization membership with role
  const membership = await workos.userManagement.createOrganizationMembership({
    userId,
    organizationId,
    roleSlug,
  });

  return membership;
}

/**
 * Update a user's role
 */
export async function updateUserRole(
  membershipId: string,
  newRoleSlug: string
) {
  const membership = await workos.userManagement.updateOrganizationMembership(
    membershipId,
    { roleSlug: newRoleSlug }
  );

  return membership;
}

/**
 * Remove a user's role (revoke access)
 */
export async function revokeUserRole(membershipId: string) {
  await workos.userManagement.deleteOrganizationMembership(membershipId);
}

/**
 * Get all roles for a user across all their organization memberships
 */
export async function getUserRoles(userId: string) {
  const memberships = await workos.userManagement.listOrganizationMemberships({
    userId,
  });

  return memberships.data.map(m => ({
    organizationId: m.organizationId,
    role: m.role?.slug,
  }));
}
```

## Part 4: WorkOS Webhooks  -  Sync to Convex

**File: `app/api/webhooks/workos/route.ts`**

```typescript
import { NextRequest, NextResponse } from "next/server";
import { Webhook } from "@workos-inc/node";
import { api } from "@/convex/_generated/api";
import { ConvexHttpClient } from "convex/browser";

const convex = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);
const webhookSecret = process.env.WORKOS_WEBHOOK_SECRET!;

export async function POST(request: NextRequest) {
  const payload = await request.text();
  const sigHeader = request.headers.get("workos-signature");

  if (!sigHeader) {
    return NextResponse.json({ error: "Missing signature" }, { status: 400 });
  }

  // Verify webhook signature
  let event;
  try {
    event = Webhook.constructEvent({
      payload,
      sigHeader,
      secret: webhookSecret,
    });
  } catch (error) {
    console.error("Webhook signature verification failed");
    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
  }

  // Route by event type
  switch (event.event) {
    case "user.created":
      await handleUserCreated(event.data);
      break;

    case "user.updated":
      await handleUserUpdated(event.data);
      break;

    case "user.deleted":
      await handleUserDeleted(event.data);
      break;

    case "organization_membership.created":
      await handleMembershipCreated(event.data);
      break;

    case "organization_membership.updated":
      await handleMembershipUpdated(event.data);
      break;

    case "organization_membership.deleted":
      await handleMembershipDeleted(event.data);
      break;

    case "session.created":
      await handleSessionCreated(event.data);
      break;

    default:
      console.log(`Unhandled webhook event: ${event.event}`);
  }

  return NextResponse.json({ received: true });
}

/**
 * Handler: user.created
 * Sync new WorkOS user to Convex users table
 */
async function handleUserCreated(data: any) {
  await convex.mutation(api.users.syncFromWorkOS, {
    workosId: data.id,
    email: data.email,
    name: `${data.firstName || ""} ${data.lastName || ""}`.trim(),
    emailVerified: data.emailVerified,
  });
}

/**
 * Handler: user.updated
 * Sync profile changes to Convex
 */
async function handleUserUpdated(data: any) {
  await convex.mutation(api.users.updateFromWorkOS, {
    workosId: data.id,
    email: data.email,
    name: `${data.firstName || ""} ${data.lastName || ""}`.trim(),
  });
}

/**
 * Handler: user.deleted
 * Soft delete in Convex (anonymize after 30 days via cron)
 */
async function handleUserDeleted(data: any) {
  await convex.mutation(api.users.softDeleteFromWorkOS, {
    workosId: data.id,
  });
}

/**
 * Handler: organization_membership.created
 * THIS IS THE CRITICAL RBAC SYNC POINT
 * When a user is added to a WorkOS org with a role, mirror that
 * role assignment into Convex so every query/mutation can check it.
 */
async function handleMembershipCreated(data: any) {
  const { userId, organizationId, role } = data;

  // Determine product + entity type from organization metadata
  const org = await getWorkOSOrganization(organizationId);
  const product = org.metadata?.product; // e.g., "edumyles"
  const entityType = org.metadata?.entityType; // "platform", "network", "agency", "reseller", "partner", "client"
  const entityId = org.metadata?.entityId; // Convex ID of the network/agency/reseller/org

  await convex.mutation(api.users.assignRole, {
    workosUserId: userId,
    product,
    role: role.slug,
    entityType,
    entityId,
  });

  // Audit log
  await convex.mutation(api.audit.log, {
    event: "role_assigned",
    userId,
    entity: "users",
    entityId: userId,
    after: { product, role: role.slug, entityType, entityId },
  });
}

/**
 * Handler: organization_membership.updated
 * Role changed  -  force re-authentication
 */
async function handleMembershipUpdated(data: any) {
  const { userId, organizationId, role } = data;

  const org = await getWorkOSOrganization(organizationId);
  const product = org.metadata?.product;

  await convex.mutation(api.users.updateRole, {
    workosUserId: userId,
    product,
    newRole: role.slug,
  });

  // CRITICAL: Force session invalidation on role change
  await convex.mutation(api.sessions.invalidateAllForUser, {
    userId,
    reason: "role_changed",
  });
}

/**
 * Handler: organization_membership.deleted
 * Role revoked  -  clear access immediately
 */
async function handleMembershipDeleted(data: any) {
  const { userId, organizationId } = data;

  const org = await getWorkOSOrganization(organizationId);
  const product = org.metadata?.product;

  await convex.mutation(api.users.revokeRole, {
    workosUserId: userId,
    product,
  });

  // Force session invalidation
  await convex.mutation(api.sessions.invalidateAllForUser, {
    userId,
    reason: "role_revoked",
  });
}

/**
 * Handler: session.created
 * Log login event for audit trail
 */
async function handleSessionCreated(data: any) {
  await convex.mutation(api.audit.log, {
    event: "login",
    userId: data.userId,
    ipAddress: data.ipAddress || "unknown",
    userAgent: data.userAgent || "unknown",
  });
}

async function getWorkOSOrganization(organizationId: string) {
  const { WorkOS } = await import("@workos-inc/node");
  const workos = new WorkOS(process.env.WORKOS_API_KEY!);
  return workos.organizations.getOrganization(organizationId);
}
```

## Part 5: Organization Metadata Schema

When creating a WorkOS organization, attach metadata that ties it back to the Convex entity. This is what `handleMembershipCreated` reads to know what kind of role assignment is happening.

```typescript
// lib/workos-organizations.ts
import { WorkOS } from "@workos-inc/node";

const workos = new WorkOS(process.env.WORKOS_API_KEY!);

/**
 * Create WorkOS organization for a network
 */
export async function createNetworkOrganization(
  networkId: string,
  networkName: string,
  product: string
) {
  return workos.organizations.createOrganization({
    name: `${product}  -  Network ${networkName}`,
    metadata: {
      product,
      entityType: "network",
      entityId: networkId,
    },
  });
}

/**
 * Create WorkOS organization for an agency
 */
export async function createAgencyOrganization(
  agencyId: string,
  agencyName: string,
  product: string
) {
  return workos.organizations.createOrganization({
    name: `${product}  -  Agency ${agencyName}`,
    metadata: {
      product,
      entityType: "agency",
      entityId: agencyId,
    },
  });
}

/**
 * Create WorkOS organization for a reseller
 */
export async function createResellerOrganization(
  resellerId: string,
  resellerName: string,
  product: string
) {
  return workos.organizations.createOrganization({
    name: `${product}  -  Reseller ${resellerName}`,
    metadata: {
      product,
      entityType: "reseller",
      entityId: resellerId,
    },
  });
}

/**
 * Create WorkOS organization for a client (tenant)
 */
export async function createClientOrganization(
  organizationId: string,
  organizationName: string,
  product: string
) {
  return workos.organizations.createOrganization({
    name: `${product}  -  Client ${organizationName}`,
    metadata: {
      product,
      entityType: "client",
      entityId: organizationId,
    },
  });
}

/**
 * Create the singleton Platform org (run once per product, at setup)
 */
export async function createPlatformOrganization(product: string) {
  return workos.organizations.createOrganization({
    name: `${product}  -  Platform`,
    metadata: {
      product,
      entityType: "platform",
      entityId: "singleton",
    },
  });
}
```

## Part 6: OAuth Redirect Configuration

Each subdomain needs its own registered redirect URI in WorkOS, since the callback handler must know which panel triggered the login.

```
WorkOS Dashboard → Redirects → Add the following per product:

Production:
├─ https://admin.edumyles.com/auth/callback
├─ https://network.edumyles.com/auth/callback
├─ https://agency.edumyles.com/auth/callback
├─ https://reseller.edumyles.com/auth/callback
├─ https://partner.edumyles.com/auth/callback
└─ https://*.edumyles.com/auth/callback        (wildcard for tenant subdomains)

Staging:
├─ https://admin-staging.edumyles.com/auth/callback
├─ https://network-staging.edumyles.com/auth/callback
└─ (repeat pattern for staging)

Development:
├─ http://admin.edumyles.localhost:3000/auth/callback
├─ http://network.edumyles.localhost:3000/auth/callback
└─ (repeat pattern for local dev)

Repeat this entire block for every product:
mylesnet, agrimyles, mylescare, mylescrm, mylesprop, eduryde
```

**Note:** WorkOS wildcard redirect support varies by plan tier  -  if wildcards aren't available, register each known tenant subdomain explicitly as it's provisioned (automate this in the client provisioning mutation).

```typescript
// Called automatically when a client is provisioned
export async function registerTenantRedirect(subdomain: string, product: string) {
  const workos = new WorkOS(process.env.WORKOS_API_KEY!);

  await workos.userManagement.addRedirectUri({
    uri: `https://${subdomain}.${product}.com/auth/callback`,
  });
}
```

## Part 7: 2FA Enforcement Configuration

```typescript
// lib/workos-2fa.ts
import { WorkOS } from "@workos-inc/node";

const workos = new WorkOS(process.env.WORKOS_API_KEY!);

const MANDATORY_2FA_ROLES = [
  "platform_admin",
  "operator_manager",
  "agency_super_admin",
  "reseller_super_admin",
];

/**
 * Enforce 2FA requirement at organization level in WorkOS
 * Called when creating/updating organizations for mandatory-2FA roles
 */
export async function enforceOrganizationMFA(organizationId: string) {
  await workos.organizations.updateOrganization(organizationId, {
    // WorkOS organization-level MFA enforcement setting
    // (exact API shape depends on WorkOS plan  -  Enterprise SSO/MFA policies)
    metadata: {
      mfa_required: "true",
    },
  });
}

/**
 * Check if a role requires mandatory 2FA
 */
export function requiresMandatory2FA(role: string): boolean {
  return MANDATORY_2FA_ROLES.includes(role);
}

/**
 * Middleware check: block access if mandatory-2FA role hasn't enabled it
 */
export async function check2FACompliance(userId: string, role: string): Promise<boolean> {
  if (!requiresMandatory2FA(role)) {
    return true; // Not required for this role
  }

  const user = await workos.userManagement.getUser(userId);

  // WorkOS exposes MFA enrollment status on the user object
  return !!(user as any).mfaEnabled;
}
```

**Enforcement point in middleware:**
```typescript
// Inside middleware.ts, after role validation
if (requiresMandatory2FA(user.role)) {
  const has2FA = await check2FACompliance(user.id, user.role);
  if (!has2FA) {
    return NextResponse.redirect(new URL("/auth/setup-2fa", request.url));
  }
}
```

## Part 8: Cross-Product Identity

A single WorkOS User ID can hold memberships across multiple product-specific organizations. The Convex `users` table mirrors this via the `roles: { product → role }` object defined in the schema doc.

```typescript
// lib/workos-cross-product.ts

/**
 * Get all product roles for a user (for the product switcher UI)
 */
export async function getUserProductRoles(workosUserId: string) {
  const memberships = await workos.userManagement.listOrganizationMemberships({
    userId: workosUserId,
  });

  const productRoles: Record<string, string> = {};

  for (const membership of memberships.data) {
    const org = await workos.organizations.getOrganization(membership.organizationId);
    const product = org.metadata?.product;

    if (product) {
      productRoles[product] = membership.role?.slug || "unknown";
    }
  }

  return productRoles;
  // Example: { edumyles: "network_operator", mylesnet: "agency_super_admin" }
```

## Part 9: Implementation Checklist

```
