           userId: target._id,
           marketId: args.marketId,
           role: args.marketRole,
           createdAt: Date.now(),
           updatedAt: Date.now(),
         });
       }
     }
     await ctx.db.insert("auditLog", {
       action: "user.update_access",
       entityTable: "users",
       entityId: target._id,
       changedBy: actor._id,
       timestamp: Date.now(),
       afterJson: JSON.stringify({
         roleIds,
         primarySlug,
         isActive: args.isActive,
         marketId: args.marketId,
         marketRole: args.marketRole,
         name: args.name,
         jobTitle: args.jobTitle,
