/**
 * MFA policy for the MylesNet platform (Security Standards; WorkOS AuthKit
 * mandatory-2FA roles).
 *
 * Enforcement model: WorkOS owns enrollment (users authenticate through
 * AuthKit and enroll factors there). This module is the app-side mirror of
 * that policy: it decides which roles *require* a verified factor and reads
 * the enrollment marker that is synced into the `users` row when identity is
 * reconciled (see `convex/workos.ts` `getWorkosMfaEnrollment` +
 * `ensureOrgMembership`). Server guards fail closed — a mandatory-2FA role
 * without a synced enrollment marker is treated as non-compliant.
 */

export const MANDATORY_MFA_ROLES = [
  "platform_owner",
  "platform_admin",
  "ops_manager",
  "finance_manager",
] as const;

export type MandatoryMfaRole = (typeof MANDATORY_MFA_ROLES)[number];

/** True when the given role slug is subject to mandatory MFA enrollment. */
export function requiresMandatory2FA(roleSlug: string | null | undefined): boolean {
  return MANDATORY_MFA_ROLES.some((slug) => slug === roleSlug);
}

/**
 * True when the account record proves MFA compliance.
 *
 * `user.mfaEnrolledAt` is set from WorkOS at reconcile time. A missing marker
 * on a mandatory role is a policy violation; on non-mandatory roles a missing
 * marker is fine (opt-in MFA is still allowed).
 */
export function isMfaCompliant(
  roleSlugs: Array<string | null | undefined>,
  user: { mfaEnrolledAt?: number } | null | undefined,
): boolean {
  const needsMfa = roleSlugs.some((slug) => requiresMandatory2FA(slug));
  if (!needsMfa) return true;
  return typeof user?.mfaEnrolledAt === "number" && user.mfaEnrolledAt > 0;
}

/** List the mandatory-2FA role slugs a set of roles actually includes. */
export function unmetMfaRoles(roleSlugs: Array<string | null | undefined>): string[] {
  return MANDATORY_MFA_ROLES.filter((slug) => roleSlugs.includes(slug));
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  MANDATORY_MFA_ROLES,
  isMfaCompliant,
  requiresMandatory2FA,
  unmetMfaRoles,
} from "./mfa";

test("MANDATORY_MFA_ROLES covers every privileged platform role", () => {
  assert.ok(MANDATORY_MFA_ROLES.includes("platform_owner"));
  assert.ok(MANDATORY_MFA_ROLES.includes("platform_admin"));
});

test("requiresMandatory2FA is true only for mandatory roles", () => {
  assert.equal(requiresMandatory2FA("platform_owner"), true);
  assert.equal(requiresMandatory2FA("platform_admin"), true);
  assert.equal(requiresMandatory2FA("ops_manager"), true);
  assert.equal(requiresMandatory2FA("finance_manager"), true);
  assert.equal(requiresMandatory2FA("platform_support"), false);
  assert.equal(requiresMandatory2FA("agent"), false);
  assert.equal(requiresMandatory2FA("network_operator"), false);
  assert.equal(requiresMandatory2FA(null), false);
  assert.equal(requiresMandatory2FA(undefined), false);
});

test("isMfaCompliant fails closed for mandatory roles without a marker", () => {
  assert.equal(isMfaCompliant(["platform_owner"], null), false);
  assert.equal(isMfaCompliant(["platform_admin"], {}), false);
  assert.equal(isMfaCompliant(["platform_owner"], { mfaEnrolledAt: 0 }), false);
  assert.equal(isMfaCompliant(["platform_owner"], {}), false);
  assert.equal(isMfaCompliant(["platform_owner"], { mfaEnrolledAt: 1750000000000 }), true);
});

test("isMfaCompliant is lax for roles outside the mandatory set", () => {
  assert.equal(isMfaCompliant(["agent"], null), true);
  assert.equal(isMfaCompliant(["platform_support"], null), true);
  assert.equal(isMfaCompliant([], null), true);
  assert.equal(isMfaCompliant(["network_operator"], null), true);
  assert.equal(isMfaCompliant(undefined, null), true);
});

test("unmetMfaRoles reports only the mandatory roles actually held", () => {
  assert.deepEqual(unmetMfaRoles(["platform_owner"]), ["platform_owner"]);
  assert.deepEqual(unmetMfaRoles(["platform_support"]), []);
  assert.deepEqual(
    unmetMfaRoles(["platform_owner", "agent", "ops_manager"]),
    ["platform_owner", "ops_manager"],
  );
  assert.deepEqual(unmetMfaRoles([]), []);
});

