input.newString:
function isActiveUser(user: Doc<"users">): boolean {
  return user.isActive !== false && user.deactivatedAt === undefined;
}

/**
 * Enforce the mandatory-2FA policy (lib/mfa). WorkOS owns enrollment; this is
 * the app-side fail-closed check on the synced marker. Ops can dial it to
 * shadow mode via env flags (RBAC shadow mode, doc 06); the default is full
 * enforcement.
 */
function assertMfaCompliance(user: Doc<"users">, roles: ResolvedRole[]): void {
  const roleSlugs = roles.map((role) => role.slug);
  if (isMfaCompliant(roleSlugs, user)) return;

  const shadowMode = process.env.NEXT_PUBLIC_ENABLE_RBAC_SHADOW_MODE === "true";
  const level = process.env.NEXT_PUBLIC_RBAC_ENFORCEMENT_LEVEL ?? "full";
  if (shadowMode || level === "off" || level === "partial") return;

  const required = roles
    .map((role) => role.slug)
    .filter((slug) => MANDATORY_MFA_ROLES.includes(slug as never));
  throw new Error(
    `Unauthorized: multi-factor authentication is required for role(s): ${required.join(", ")}`,
  );
}

/** Keep the system role slugs reachable from auth consumers. */
export { SYSTEM_ROLE_SLUGS };

