 /* ============================================================
    MylesNet public landing — premium visual system (v2).
    Built on the shared design-token contract only (var(--token)).
    All effects (gradients, glows, glass, tints) use color-mix of
    tokens so nothing introduces a raw colour of its own.
    ============================================================ */

 :root {
   /* Component-scope tokens derived from the shared contract */
   --landing-container: 1140px;
   --landing-radius: 20px;
   --landing-radius-lg: 26px;
   --landing-glass: color-mix(in srgb, var(--surface) 78%, transparent);
   --landing-glass-border: color-mix(in srgb, var(--line) 65%, transparent);
   --landing-primary-glow: color-mix(in srgb, var(--primary) 32%, transparent);
   --landing-accent-glow: color-mix(in srgb, var(--accent) 40%, transparent);
   --landing-ink-start: var(--sidebar-canvas);
   --landing-ink-end: var(--sidebar-canvas-end);
   --landing-ink-text: var(--sidebar-text);
   --landing-ink-muted: var(--sidebar-muted);
   --landing-surface-tint: color-mix(in srgb, var(--primary) 6%, var(--surface));

   /* Typography — Geist UI/body, Space Grotesk display, Geist Mono accents */
   --landing-font-sans: var(--font-geist-sans), Arial, Helvetica, sans-serif;
   --landing-font-display: var(--font-landing-display), var(--font-geist-sans), Arial, Helvetica, sans-serif;
   --landing-font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
 }

 .landing-main {
   min-height: 70vh;
   background: var(--canvas);
   color: var(--text);
 }

 .landing-container {
   width: min(var(--landing-container), 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 /* ============================================================
    Header — sticky glass
    ============================================================ */
 .landing-header {
   position: sticky;
   top: 0;
   z-index: 40;
   border-bottom: 1px solid var(--landing-glass-border);
   background: var(--landing-glass);
   backdrop-filter: blur(14px);
   -webkit-backdrop-filter: blur(14px);
 }

 .landing-nav {
   display: flex;
   min-height: 72px;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
 }

 .landing-brand {
   display: inline-flex;
   align-items: center;
   gap: 12px;
   color: var(--text-strong);
   text-decoration: none;
 }

 .landing-logo {
   display: block;
   width: auto;
   max-width: 148px;
   height: 42px;
   object-fit: contain;
   border-radius: 8px;
   background: var(--surface);
   padding: 3px 6px;
   box-shadow: var(--shadow-sm);
 }

 .landing-nav-links {
   display: flex;
   align-items: center;
   gap: 4px;
 }

 .landing-nav-link {
   position: relative;
   display: inline-block;
   padding: 9px 13px;
   border-radius: 9999px;
   color: var(--text);
   font-size: 14.5px;
   font-weight: 650;
   text-decoration: none;
   transition: color var(--duration-fast) var(--ease-out), background-color var(--duration-fast) var(--ease-out);
 }

 .landing-nav-link:hover {
   color: var(--text-strong);
   background: color-mix(in srgb, var(--primary) 10%, transparent);
 }

 .landing-nav-cta {
   margin-left: 12px;
 }

 .landing-nav-toggle {
   display: none;
   place-items: center;
   height: 42px;
   width: 42px;
   border: 1px solid var(--line);
   border-radius: 12px;
   background: var(--surface);
   color: var(--text-strong);
   cursor: pointer;
   transition: border-color var(--duration-fast) var(--ease-out);
 }

 .landing-nav-toggle:hover {
   border-color: var(--line-strong);
 }

 .landing-mobile-menu {
   display: none;
 }

 /* ============================================================
    Buttons
    ============================================================ */
 .landing-cta-button {
   display: inline-flex;
   min-height: 46px;
   align-items: center;
   justify-content: center;
   gap: 8px;
   border-radius: 9999px;
   border: 1px solid transparent;
   background:
     linear-gradient(180deg, color-mix(in srgb, var(--primary) 92%, var(--primary-hover)) 0%, var(--primary) 100%);
   color: var(--primary-action-foreground);
   padding: 12px 24px;
   font: inherit;
   font-size: 15px;
   font-weight: 800;
   text-decoration: none;
   box-shadow: 0 8px 24px var(--landing-primary-glow), inset 0 1px 0 color-mix(in srgb, var(--primary-foreground) 18%, transparent);
   transition: transform var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out), filter var(--duration-fast) var(--ease-out);
 }

 .landing-cta-button:hover {
   filter: brightness(1.04);
   transform: translateY(-1px);
   box-shadow: 0 12px 30px var(--landing-primary-glow), inset 0 1px 0 color-mix(in srgb, var(--primary-foreground) 18%, transparent);
 }

 .landing-secondary-button {
   display: inline-flex;
   min-height: 46px;
   align-items: center;
   justify-content: center;
   gap: 8px;
   border: 1px solid var(--line-strong);
   border-radius: 9999px;
   background: color-mix(in srgb, var(--surface) 70%, transparent);
   color: var(--text-strong);
   padding: 12px 24px;
   font: inherit;
   font-size: 15px;
   font-weight: 700;
   text-decoration: none;
   transition: border-color var(--duration-fast) var(--ease-out), background-color var(--duration-fast) var(--ease-out), transform var(--duration-fast) var(--ease-out);
 }

 .landing-secondary-button:hover {
   border-color: var(--primary);
   background: color-mix(in srgb, var(--primary) 8%, var(--surface));
   transform: translateY(-1px);
 }

 .landing-text-link {
   display: inline-flex;
   align-items: center;
   gap: 6px;
   color: var(--primary-text);
   font-size: 14px;
   font-weight: 800;
   text-decoration: none;
   transition: gap var(--duration-fast) var(--ease-out);
 }

 .landing-text-link:hover {
   gap: 9px;
 }

 /* ============================================================
    Hero
    ============================================================ */
 .landing-hero {
   position: relative;
   overflow: hidden;
   padding: clamp(72px, 9vw, 112px) 0 clamp(56px, 7vw, 88px);
   text-align: center;
 }

 .landing-hero-orb {
   position: absolute;
   z-index: 0;
   border-radius: 9999px;
   pointer-events: none;
   filter: blur(70px);
   animation: landing-float 9s ease-in-out infinite;
 }

 .landing-hero-orb-a {
   top: -140px;
   left: -80px;
   height: 420px;
   width: 420px;
   background: radial-gradient(circle, color-mix(in srgb, var(--primary) 30%, transparent) 0%, transparent 70%);
 }

 .landing-hero-orb-b {
   top: 40px;
   right: -140px;
   height: 480px;
   width: 480px;
   background: radial-gradient(circle, color-mix(in srgb, var(--accent) 26%, transparent) 0%, transparent 70%);
   animation-delay: 3s;
 }

 .landing-hero-orb-c {
   bottom: -180px;
   left: 32%;
   height: 420px;
   width: 560px;
   background: radial-gradient(circle, color-mix(in srgb, var(--primary) 16%, transparent) 0%, transparent 70%);
   animation-delay: 6s;
 }

 @keyframes landing-float {
   0%, 100% { transform: translate3d(0, 0, 0); }
   50% { transform: translate3d(0, -22px, 0); }
 }

 .landing-gridlines {
   position: absolute;
   inset: 0;
   z-index: 0;
   pointer-events: none;
   background-image:
     linear-gradient(color-mix(in srgb, var(--text-strong) 3%, transparent) 1px, transparent 1px),
     linear-gradient(90deg, color-mix(in srgb, var(--text-strong) 3%, transparent) 1px, transparent 1px);
   background-size: 44px 44px;
   mask-image: radial-gradient(ellipse 90% 70% at 50% 0%, black 30%, transparent 78%);
   -webkit-mask-image: radial-gradient(ellipse 90% 70% at 50% 0%, black 30%, transparent 78%);
 }

 .landing-hero-inner {
   position: relative;
   z-index: 1;
   max-width: 860px;
   margin: 0 auto;
 }

 .landing-hero-tagline {
   display: inline-flex;
   align-items: center;
   gap: 9px;
   margin: 0 auto 20px;
   padding: 9px 20px;
   border-radius: 9999px;
   background: var(--primary-action);
   color: var(--primary-action-foreground);
   font-size: 12.5px;
   font-weight: 800;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   box-shadow: 0 12px 30px color-mix(in srgb, var(--primary-action) 32%, transparent);
 }

 .landing-hero-tagline::before {
   content: "";
   width: 7px;
   height: 7px;
   border-radius: 9999px;
   background: color-mix(in srgb, var(--primary-action-foreground) 88%, transparent);
   box-shadow: 0 0 0 4px color-mix(in srgb, var(--primary-action-foreground) 22%, transparent);
 }

 .landing-hero-eyebrow {
   display: inline-flex;
   align-items: center;
   gap: 9px;
   border-radius: 9999px;
   border: 1px solid color-mix(in srgb, var(--primary) 30%, var(--line));
   background: color-mix(in srgb, var(--primary) 8%, var(--surface));
   color: var(--primary-text);
   padding: 7px 16px;
   font-size: 12.5px;
   font-weight: 800;
   letter-spacing: 0.07em;
   text-transform: uppercase;
 }

 .landing-eyebrow-dot {
   height: 8px;
   width: 8px;
   border-radius: 9999px;
   background: var(--primary);
   box-shadow: 0 0 0 4px color-mix(in srgb, var(--primary) 22%, transparent);
   animation: landing-pulse 2.4s ease-in-out infinite;
 }

 @keyframes landing-pulse {
   0%, 100% { opacity: 1; }
   50% { opacity: 0.45; }
 }

 .landing-hero-title {
   margin: 26px auto 0;
   color: var(--text-strong);
   font-size: clamp(40px, 6.4vw, 76px);
   line-height: 1.04;
   font-weight: 800;
   letter-spacing: -0.03em;
   text-wrap: balance;
 }

 .landing-hero-title .landing-title-accent {
   position: relative;
   display: inline-block;
   color: var(--primary-text);
 }

 .landing-hero-subtitle {
   margin: 24px auto 0;
   max-width: 640px;
   color: var(--muted);
   font-size: clamp(17px, 2.1vw, 20px);
   line-height: var(--line-height-relaxed);
   text-wrap: pretty;
 }

 .landing-hero-actions {
   position: relative;
   z-index: 1;
   display: flex;
   justify-content: center;
   align-items: center;
   gap: 14px;
   margin-top: 36px;
   flex-wrap: wrap;
 }

 .landing-hero-note {
   margin: 16px auto 0;
   color: var(--muted);
   font-size: 13px;
 }

 .landing-hero-attributes {
   display: flex;
   flex-wrap: wrap;
   justify-content: center;
   gap: 10px;
   margin-top: 34px;
 }

 .landing-attribute-chip {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   border-radius: 9999px;
   border: 1px solid var(--line);
   background: color-mix(in srgb, var(--surface) 72%, transparent);
   color: var(--text);
   padding: 8px 15px;
   font-size: 13px;
   font-weight: 700;
 }

 .landing-attribute-chip svg {
   color: var(--primary-text);
 }

 /* ============================================================
    Product preview (CSS dashboard mock)
    ============================================================ */
 .landing-preview-wrap {
   position: relative;
   z-index: 1;
   max-width: 880px;
   margin: clamp(44px, 6vw, 72px) auto 0;
   perspective: 1200px;
 }

 .landing-preview-glow {
   position: absolute;
   inset: -8% -4%;
   z-index: 0;
   border-radius: 36px;
   background:
     radial-gradient(60% 55% at 22% 12%, var(--landing-primary-glow) 0%, transparent 65%),
     radial-gradient(55% 60% at 84% 22%, var(--landing-accent-glow) 0%, transparent 62%);
   filter: blur(26px);
 }

 .landing-preview {
   position: relative;
   z-index: 1;
   overflow: hidden;
   border: 1px solid var(--line-strong);
   border-radius: var(--landing-radius-lg);
   background: var(--surface);
   box-shadow: 0 40px 90px var(--shadow-lg), 0 0 0 1px color-mix(in srgb, var(--line) 50%, transparent);
   transform: rotateX(2.5deg) translateY(0);
   transition: transform var(--duration-slow) var(--ease-out);
 }

 .landing-preview:hover {
   transform: rotateX(0deg) translateY(-6px);
 }

 .landing-preview-bar {
   display: flex;
   align-items: center;
   gap: 8px;
   padding: 13px 18px;
   border-bottom: 1px solid var(--line);
   background: color-mix(in srgb, var(--surface-muted) 55%, var(--surface));
 }

 .landing-preview-dot {
   height: 10px;
   width: 10px;
   border-radius: 9999px;
   background: var(--line-strong);
 }

 .landing-preview-dot:first-child { background: var(--danger); }
 .landing-preview-dot:nth-child(2) { background: var(--warning); }
 .landing-preview-dot:nth-child(3) { background: var(--success); }

 .landing-preview-url {
   margin-left: 12px;
   flex: 1;
   border-radius: 9999px;
   background: var(--surface);
   border: 1px solid var(--line);
   color: var(--muted);
   padding: 7px 14px;
   font-size: 12px;
   text-align: left;
 }

 .landing-preview-body {
   display: grid;
   grid-template-columns: 210px minmax(0, 1fr);
   min-height: 360px;
 }

 .landing-preview-side {
   display: flex;
   flex-direction: column;
   gap: 4px;
   padding: 20px 14px;
   background: linear-gradient(180deg, var(--landing-ink-start), var(--landing-ink-end));
   color: var(--landing-ink-text);
 }

 .landing-preview-side-brand {
   display: flex;
   align-items: center;
   gap: 8px;
   margin: 0 6px 16px;
   font-size: 13px;
   font-weight: 800;
   color: var(--surface);
 }

 .landing-preview-side-item {
   display: flex;
   align-items: center;
   gap: 9px;
   padding: 9px 11px;
   border-radius: 10px;
   font-size: 12.5px;
   font-weight: 650;
   color: var(--landing-ink-muted);
 }

 .landing-preview-side-item-active {
   background: color-mix(in srgb, var(--primary) 88%, transparent);
   color: var(--surface);
   box-shadow: 0 6px 16px color-mix(in srgb, var(--primary) 40%, transparent);
 }

 .landing-preview-main {
   display: flex;
   flex-direction: column;
   gap: 16px;
   padding: 22px 24px;
   background:
     radial-gradient(120% 90% at 100% 0%, color-mix(in srgb, var(--primary) 7%, transparent) 0%, transparent 55%),
     var(--surface);
 }

 .landing-preview-head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
 }

 .landing-preview-head h4 {
   margin: 0;
   color: var(--text-strong);
   font-size: 16px;
   letter-spacing: -0.01em;
 }

 .landing-preview-head p {
   margin: 3px 0 0;
   color: var(--muted);
   font-size: 12px;
 }

 .landing-preview-kpis {
   display: grid;
   grid-template-columns: repeat(3, minmax(0, 1fr));
   gap: 12px;
 }

 .landing-preview-kpi {
   border: 1px solid var(--line);
   border-radius: 16px;
   background: color-mix(in srgb, var(--surface) 85%, transparent);
   padding: 14px 16px;
   box-shadow: var(--shadow-sm);
 }

 .landing-preview-kpi span {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   color: var(--muted);
   font-size: 11px;
   font-weight: 800;
   letter-spacing: 0.04em;
   text-transform: uppercase;
 }

 .landing-preview-kpi span svg {
   color: var(--primary-text);
 }

 .landing-preview-kpi strong {
   display: block;
   margin-top: 8px;
   color: var(--text-strong);
   font-size: 24px;
   letter-spacing: -0.03em;
 }

 .landing-preview-kpi small {
   display: block;
   margin-top: 3px;
   color: var(--success);
   font-size: 11.5px;
   font-weight: 700;
 }

 .landing-preview-chart {
   display: flex;
   align-items: flex-end;
   justify-content: space-between;
   gap: 10px;
   height: 92px;
   border-radius: 16px;
   border: 1px solid var(--line);
   background: color-mix(in srgb, var(--surface-muted) 50%, var(--surface));
   padding: 16px 18px;
 }

 .landing-preview-bar {
   flex: 1;
   max-width: 34px;
   border-radius: 8px 8px 4px 4px;
   background: linear-gradient(180deg, var(--primary) 0%, color-mix(in srgb, var(--primary) 55%, var(--surface)) 100%);
   animation: landing-grow 1.1s var(--ease-out) backwards;
 }

 @keyframes landing-grow {
   from { transform: scaleY(0.12); transform-origin: bottom; }
   to { transform: scaleY(1); transform-origin: bottom; }
 }

 .landing-preview-rows {
   display: grid;
   gap: 9px;
 }

 .landing-preview-row {
   display: flex;
   align-items: center;
   gap: 11px;
   padding: 11px 13px;
   border: 1px solid var(--line);
   border-radius: 13px;
   background: var(--surface);
 }

 .landing-preview-row-icon {
   display: grid;
   height: 32px;
   width: 32px;
   flex: none;
   place-items: center;
   border-radius: 10px;
   background: var(--landing-surface-tint);
   color: var(--primary-text);
 }

 .landing-preview-row p {
   flex: 1;
   margin: 0;
   color: var(--text);
   font-size: 13px;
   font-weight: 700;
 }

 .landing-preview-row small {
   color: var(--muted);
   font-size: 12px;
   font-weight: 700;
 }

 .landing-preview-row .landing-status-chip {
   flex: none;
 }

 .landing-status-chip {
   display: inline-flex;
   align-items: center;
   gap: 5px;
   border-radius: 9999px;
   padding: 4px 10px;
   font-size: 11px;
   font-weight: 800;
   background: var(--success-bg);
   color: var(--success);
 }

 /* ============================================================
    Audiences strip
    ============================================================ */
 .landing-audiences {
   padding: 0 0 clamp(56px, 7vw, 84px);
 }

 .landing-audiences-label {
   margin: 0 0 18px;
   color: var(--muted);
   font-size: 12px;
   font-weight: 800;
   letter-spacing: 0.12em;
   text-align: center;
   text-transform: uppercase;
 }

 .landing-audiences-pills {
   display: flex;
   flex-wrap: wrap;
   justify-content: center;
   gap: 10px;
 }

 .landing-audience-pill {
   border-radius: 9999px;
   border: 1px solid var(--line);
   background: var(--surface);
   color: var(--text);
   padding: 9px 18px;
   font-size: 13.5px;
   font-weight: 700;
   box-shadow: var(--shadow-sm);
   transition: border-color var(--duration-fast) var(--ease-out), transform var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
 }

 .landing-audience-pill:hover {
   border-color: color-mix(in srgb, var(--primary) 55%, var(--line));
   box-shadow: var(--shadow-md);
   transform: translateY(-2px);
 }

 /* ============================================================
    Section scaffolding
    ============================================================ */
 .landing-section {
   padding: clamp(68px, 9vw, 116px) 0;
   scroll-margin-top: 88px;
 }

 .landing-section-alt {
   background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 4%, var(--canvas)) 0%, var(--canvas) 100%);
 }

 .landing-section-inner {
   width: min(var(--landing-container), 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 .landing-section-head {
   max-width: 700px;
   margin: 0 auto clamp(40px, 5vw, 56px);
   text-align: center;
 }

 .landing-section-head-left {
   margin-inline: 0;
   text-align: left;
 }

 .landing-section-kicker {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   margin: 0 0 14px;
   color: var(--primary-text);
   font-size: 12.5px;
   font-weight: 800;
   letter-spacing: 0.11em;
   text-transform: uppercase;
 }

 .landing-section-kicker::before {
   content: "";
   height: 2px;
   width: 26px;
   border-radius: 9999px;
   background: linear-gradient(90deg, var(--primary), color-mix(in srgb, var(--primary) 35%, transparent));
 }

 .landing-section-head-center .landing-section-kicker::after {
   content: "";
   height: 2px;
   width: 26px;
   border-radius: 9999px;
   background: linear-gradient(90deg, color-mix(in srgb, var(--primary) 35%, transparent), var(--primary));
 }

 .landing-section-head-center .landing-section-kicker {
   justify-content: center;
 }

 .landing-section-title {
   margin: 0;
   color: var(--text-strong);
   font-size: clamp(30px, 4.2vw, 46px);
   line-height: 1.05;
   font-weight: 800;
   letter-spacing: -0.025em;
   text-wrap: balance;
 }

 .landing-section-subtitle {
   margin: 18px auto 0;
   max-width: 600px;
   color: var(--muted);
   font-size: 16.5px;
   line-height: var(--line-height-relaxed);
   text-wrap: pretty;
 }

 .landing-section-head-left .landing-section-subtitle {
   margin-inline: 0;
 }

 .landing-kicker-row {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
   margin-bottom: clamp(28px, 4vw, 40px);
 }

 /* ============================================================
    Stats band (dark ink) — sourced industry figures
    ============================================================ */
 .landing-stats {
   position: relative;
   overflow: hidden;
   padding: clamp(64px, 8vw, 104px) 0;
   background: linear-gradient(150deg, var(--landing-ink-start) 0%, var(--landing-ink-end) 100%);
   color: var(--landing-ink-text);
 }

 .landing-stats::before {
   content: "";
   position: absolute;
   inset: 0;
   background-image:
     linear-gradient(color-mix(in srgb, var(--surface) 4%, transparent) 1px, transparent 1px),
     linear-gradient(90deg, color-mix(in srgb, var(--surface) 4%, transparent) 1px, transparent 1px);
   background-size: 52px 52px;
   mask-image: radial-gradient(ellipse 80% 90% at 50% 0%, black 25%, transparent 75%);
   -webkit-mask-image: radial-gradient(ellipse 80% 90% at 50% 0%, black 25%, transparent 75%);
   pointer-events: none;
 }

 .landing-stats-inner {
   position: relative;
   z-index: 1;
   width: min(var(--landing-container), 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 .landing-stats .landing-section-kicker {
   color: color-mix(in srgb, var(--primary) 75%, var(--surface));
 }

 .landing-stats .landing-section-title {
   color: var(--surface);
 }

 .landing-stats .landing-section-subtitle {
   color: var(--landing-ink-muted);
 }

 .landing-stats-grid {
   display: grid;
   grid-template-columns: repeat(4, minmax(0, 1fr));
   gap: 22px;
   margin-top: clamp(36px, 4vw, 48px);
 }

 .landing-stat-card {
   position: relative;
   border: 1px solid color-mix(in srgb, var(--surface) 16%, transparent);
   border-radius: var(--landing-radius);
   background: linear-gradient(170deg, color-mix(in srgb, var(--surface) 9%, transparent) 0%, transparent 100%);
   padding: 26px 24px;
   backdrop-filter: blur(4px);
 }

 .landing-stat-value {
   display: block;
   color: var(--primary);
   font-size: clamp(34px, 4vw, 46px);
   font-weight: 800;
   letter-spacing: -0.03em;
   line-height: 1;
 }

 .landing-stat-label {
   display: block;
   margin-top: 12px;
   color: var(--surface);
   font-size: 15px;
   font-weight: 800;
 }

 .landing-stat-detail {
   display: block;
   margin-top: 9px;
   color: var(--landing-ink-muted);
   font-size: 13px;
   line-height: 1.55;
 }

 .landing-stat-source {
   display: inline-flex;
   align-items: center;
   gap: 5px;
   margin-top: 14px;
   color: color-mix(in srgb, var(--sidebar-muted) 75%, var(--surface));
   font-size: 11.5px;
   font-weight: 700;
   text-decoration: none;
   transition: color var(--duration-fast) var(--ease-out);
 }

 .landing-stat-source:hover {
   color: var(--primary);
 }

 .landing-stats-note {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 8px 18px;
   margin-top: 38px;
   padding-top: 22px;
   border-top: 1px solid color-mix(in srgb, var(--surface) 14%, transparent);
   color: var(--landing-ink-muted);
   font-size: 12px;
 }

 .landing-stats-note a {
   color: color-mix(in srgb, var(--sidebar-muted) 70%, var(--surface));
   text-decoration: none;
   font-weight: 700;
 }

 .landing-stats-note a:hover {
   color: var(--primary);
 }

 /* ============================================================
    Bento feature grid
    ============================================================ */
 .landing-bento {
   display: grid;
   grid-template-columns: repeat(6, minmax(0, 1fr));
   gap: 18px;
 }

 .landing-bento-card {
   position: relative;
   display: flex;
   flex-direction: column;
   gap: 14px;
   overflow: hidden;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: linear-gradient(180deg, var(--surface) 0%, color-mix(in srgb, var(--surface-muted) 55%, var(--surface)) 100%);
   padding: clamp(22px, 3vw, 30px);
   text-decoration: none;
   color: inherit;
   box-shadow: var(--shadow-sm);
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out), border-color var(--duration-base) var(--ease-out);
 }

 .landing-bento-card::after {
   content: "";
   position: absolute;
   right: -60px;
   top: -60px;
   height: 180px;
   width: 180px;
   border-radius: 9999px;
   background: radial-gradient(circle, color-mix(in srgb, var(--primary) 16%, transparent) 0%, transparent 70%);
   pointer-events: none;
   transition: opacity var(--duration-base) var(--ease-out);
   opacity: 0;
 }

 .landing-bento-card:hover {
   transform: translateY(-4px);
   border-color: color-mix(in srgb, var(--primary) 45%, var(--line));
   box-shadow: var(--shadow-lg);
 }

 .landing-bento-card:hover::after {
   opacity: 1;
 }

 .landing-bento-span-6 { grid-column: span 6; }
 .landing-bento-span-4 { grid-column: span 4; }
 .landing-bento-span-3 { grid-column: span 3; }
 .landing-bento-span-2 { grid-column: span 2; }

 .landing-bento-icon {
   display: grid;
   height: 48px;
   width: 48px;
   place-items: center;
   border-radius: 14px;
   border: 1px solid color-mix(in srgb, var(--primary) 30%, var(--line));
   background: color-mix(in srgb, var(--primary) 10%, var(--surface));
   color: var(--primary-text);
   box-shadow: inset 0 1px 0 color-mix(in srgb, var(--surface) 60%, transparent);
 }

 .landing-bento-card h3 {
   margin: 0;
   color: var(--text-strong);
   font-size: 20px;
   font-weight: 800;
   letter-spacing: -0.015em;
 }

 .landing-bento-card p {
   margin: 0;
   color: var(--muted);
   font-size: 14.5px;
   line-height: 1.6;
 }

 .landing-bento-tags {
   display: flex;
   flex-wrap: wrap;
   gap: 8px;
   margin-top: auto;
   padding-top: 10px;
 }

 .landing-bento-tag {
   border-radius: 9999px;
   border: 1px solid var(--line);
   background: var(--surface);
   color: var(--text);
   padding: 6px 12px;
   font-size: 12px;
   font-weight: 700;
 }

 .landing-bento-cta {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin-top: auto;
   padding-top: 8px;
   color: var(--primary-text);
   font-size: 14.5px;
   font-weight: 800;
 }

 .landing-bento-cta svg {
   transition: transform var(--duration-fast) var(--ease-out);
 }

 .landing-bento-card:hover .landing-bento-cta svg {
   transform: translateX(4px);
 }

 /* ============================================================
    Process timeline
    ============================================================ */
 .landing-process {
   display: grid;
   grid-template-columns: repeat(4, minmax(0, 1fr));
   gap: 18px;
   counter-reset: process;
 }

 .landing-process-step {
   position: relative;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: var(--surface);
   padding: 28px 26px;
   box-shadow: var(--shadow-sm);
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out);
 }

 .landing-process-step:hover {
   transform: translateY(-4px);
   box-shadow: var(--shadow-md);
 }

 .landing-process-step::before {
   content: "";
   position: absolute;
   inset: 0 0 auto 0;
   height: 4px;
   border-radius: 9999px 9999px 0 0;
   background: linear-gradient(90deg, var(--primary) 0%, color-mix(in srgb, var(--primary) 30%, transparent) 100%);
 }

 .landing-process-num {
   display: inline-grid;
   height: 42px;
   width: 42px;
   place-items: center;
   border-radius: 13px;
   background: var(--landing-ink-start);
   color: var(--surface);
   font-size: 15px;
   font-weight: 800;
   letter-spacing: 0.02em;
 }

 .landing-process-step h3 {
   margin: 18px 0 0;
   color: var(--text-strong);
   font-size: 18px;
   font-weight: 800;
   letter-spacing: -0.01em;
 }

 .landing-process-step p {
   margin: 10px 0 0;
   color: var(--muted);
   font-size: 14px;
   line-height: 1.6;
 }

 /* ============================================================
    Solutions grid
    ============================================================ */
 .landing-solutions-grid {
   display: grid;
   grid-template-columns: repeat(2, minmax(0, 1fr));
   gap: 18px;
 }

 .landing-solution-card {
   position: relative;
   display: flex;
   flex-direction: column;
   gap: 16px;
   overflow: hidden;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: var(--surface);
   padding: clamp(24px, 3vw, 32px);
   text-decoration: none;
   color: inherit;
   box-shadow: var(--shadow-sm);
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out), border-color var(--duration-base) var(--ease-out);
 }

 .landing-solution-card:hover {
   transform: translateY(-4px);
   border-color: color-mix(in srgb, var(--accent) 40%, var(--line));
   box-shadow: var(--shadow-lg);
 }

 .landing-solution-head {
   display: flex;
   align-items: center;
   gap: 14px;
 }

 .landing-solution-icon {
   display: grid;
   height: 48px;
   width: 48px;
   flex: none;
   place-items: center;
   border-radius: 14px;
   background: linear-gradient(150deg, var(--accent) 0%, color-mix(in srgb, var(--accent) 72%, var(--primary)) 100%);
   color: var(--surface);
   box-shadow: 0 10px 22px var(--landing-accent-glow);
 }

 .landing-solution-head h3 {
   margin: 0;
   color: var(--text-strong);
   font-size: 20px;
   font-weight: 800;
   letter-spacing: -0.015em;
 }

 .landing-solution-head p {
   margin: 4px 0 0;
   color: var(--muted);
   font-size: 13px;
 }

 .landing-solution-card > p {
   margin: 0;
   color: var(--muted);
   font-size: 14.5px;
   line-height: 1.6;
 }

 .landing-solution-outcomes {
   display: flex;
   flex-direction: column;
   gap: 9px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .landing-solution-outcomes li {
   display: flex;
   align-items: flex-start;
   gap: 10px;
   color: var(--text);
   font-size: 14px;
   font-weight: 600;
   line-height: 1.45;
 }

 .landing-solution-outcomes li svg {
   flex: none;
   margin-top: 2px;
   color: var(--success);
 }

 .landing-solution-card .landing-bento-cta {
   margin-top: auto;
 }

 /* ============================================================
    Comparison (without vs with MylesNet)
    ============================================================ */
 .landing-compare {
   overflow: hidden;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius-lg);
   background: var(--surface);
   box-shadow: var(--shadow-md);
 }

 .landing-compare-head,
 .landing-compare-row {
   display: grid;
   grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
   gap: 16px;
 }

 .landing-compare-head {
   padding: 22px 26px;
   background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 7%, var(--surface)), var(--surface));
   border-bottom: 1px solid var(--line);
 }

 .landing-compare-col-title {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin: 0;
   color: var(--text-strong);
   font-size: 15px;
   font-weight: 800;
 }

 .landing-compare-col-title-with {
   color: var(--primary-text);
 }

 .landing-compare-row {
   padding: 18px 26px;
   border-bottom: 1px solid var(--line);
 }

 .landing-compare-row:last-child {
   border-bottom: 0;
 }

 .landing-compare-row:nth-child(even) {
   background: color-mix(in srgb, var(--surface-muted) 45%, var(--surface));
 }

 .landing-compare-cell {
   display: flex;
   align-items: flex-start;
   gap: 10px;
   color: var(--muted);
   font-size: 14.5px;
   line-height: 1.55;
 }

 .landing-compare-cell svg {
   flex: none;
   margin-top: 3px;
 }

 .landing-compare-cell-with {
   color: var(--text);
   font-weight: 650;
 }

 .landing-compare-cell-with svg {
   color: var(--success);
 }

 /* ============================================================
    Security / trust pillars
    ============================================================ */
 .landing-trust-grid {
   display: grid;
   grid-template-columns: repeat(4, minmax(0, 1fr));
   gap: 18px;
 }

 .landing-trust-card {
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: var(--surface);
   padding: 26px 24px;
   box-shadow: var(--shadow-sm);
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out);
 }

 .landing-trust-card:hover {
   transform: translateY(-4px);
   box-shadow: var(--shadow-md);
 }

 .landing-trust-icon {
   display: grid;
   height: 44px;
   width: 44px;
   place-items: center;
   border-radius: 13px;
   background: var(--success-bg);
   color: var(--success);
 }

 .landing-trust-card h3 {
   margin: 16px 0 0;
   color: var(--text-strong);
   font-size: 17px;
   font-weight: 800;
 }

 .landing-trust-card p {
   margin: 9px 0 0;
   color: var(--muted);
   font-size: 13.5px;
   line-height: 1.6;
 }

 /* ============================================================
    FAQ
    ============================================================ */
 .landing-faq {
   width: min(760px, 100%);
   margin: 0 auto;
 }

 .landing-faq details {
   border: 1px solid var(--line);
   border-radius: 16px;
   background: var(--surface);
   box-shadow: var(--shadow-sm);
   transition: border-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out);
 }

 .landing-faq details + details {
   margin-top: 12px;
 }

 .landing-faq details:hover {
   border-color: color-mix(in srgb, var(--primary) 40%, var(--line));
 }

 .landing-faq details[open] {
   border-color: color-mix(in srgb, var(--primary) 45%, var(--line));
   box-shadow: var(--shadow-md);
 }

 .landing-faq summary {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 18px;
   padding: 20px 22px;
   color: var(--text-strong);
   font-size: 15.5px;
   font-weight: 800;
   cursor: pointer;
   list-style: none;
 }

 .landing-faq summary::-webkit-details-marker {
   display: none;
 }

 .landing-faq-summary-icon {
   display: grid;
   height: 26px;
   width: 26px;
   flex: none;
   place-items: center;
   border-radius: 9999px;
   background: var(--landing-surface-tint);
   color: var(--primary-text);
   transition: transform var(--duration-base) var(--ease-out), background-color var(--duration-base) var(--ease-out);
 }

 .landing-faq details[open] .landing-faq-summary-icon {
   transform: rotate(45deg);
   background: var(--primary);
   color: var(--surface);
 }

 .landing-faq-answer {
   margin: 0;
   padding: 0 22px 22px;
   color: var(--muted);
   font-size: 14.5px;
   line-height: 1.65;
 }

 /* ============================================================
    CTA band (dark ink)
    ============================================================ */
 .landing-cta-band {
   position: relative;
   overflow: hidden;
   padding: clamp(72px, 9vw, 120px) 0;
   text-align: center;
   background: linear-gradient(150deg, var(--landing-ink-start) 0%, var(--landing-ink-end) 100%);
   color: var(--landing-ink-text);
   scroll-margin-top: 88px;
 }

 .landing-cta-band::before {
   content: "";
   position: absolute;
   inset: 0;
   background:
     radial-gradient(55% 75% at 50% 0%, color-mix(in srgb, var(--primary) 20%, transparent) 0%, transparent 70%),
     radial-gradient(45% 60% at 85% 90%, color-mix(in srgb, var(--accent) 22%, transparent) 0%, transparent 72%);
   pointer-events: none;
 }

 .landing-cta-inner {
   position: relative;
   z-index: 1;
   width: min(760px, 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 .landing-cta-band .landing-section-kicker {
   color: color-mix(in srgb, var(--primary) 75%, var(--surface));
 }

 .landing-cta-band h2 {
   margin: 0;
   color: var(--surface);
   font-size: clamp(30px, 4.6vw, 52px);
   line-height: 1.08;
   font-weight: 800;
   letter-spacing: -0.025em;
   text-wrap: balance;
 }

 .landing-cta-band p {
   margin: 18px auto 0;
   max-width: 560px;
   color: var(--landing-ink-muted);
   font-size: 16px;
   line-height: 1.65;
 }

 .landing-cta-band .landing-hero-actions {
   margin-top: 34px;
 }

 .landing-cta-band .landing-cta-button {
   font-size: 16px;
   min-height: 52px;
   padding: 14px 32px;
 }

 .landing-cta-band .landing-secondary-button {
   border-color: color-mix(in srgb, var(--surface) 30%, transparent);
   color: var(--surface);
 }

 .landing-cta-band .landing-secondary-button:hover {
   border-color: var(--primary);
   color: var(--surface);
 }

 /* ============================================================
    Content pages (banner + prose + checklists + highlights)
    ============================================================ */
 .landing-page-banner {
   position: relative;
   overflow: hidden;
   padding: clamp(60px, 8vw, 96px) 0 clamp(36px, 4vw, 52px);
   border-bottom: 1px solid var(--line);
   background:
     radial-gradient(70% 100% at 12% 0%, color-mix(in srgb, var(--primary) 12%, transparent) 0%, transparent 60%),
     radial-gradient(60% 100% at 92% 10%, color-mix(in srgb, var(--accent) 12%, transparent) 0%, transparent 60%),
     linear-gradient(180deg, var(--surface-strong) 0%, var(--canvas) 100%);
 }

 .landing-page-banner-inner {
   position: relative;
   z-index: 1;
   width: min(var(--landing-container), 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 .landing-page-banner h1 {
   max-width: 780px;
   margin: 8px 0 0;
   color: var(--text-strong);
   font-size: clamp(34px, 5vw, 54px);
   line-height: 1.06;
   font-weight: 800;
   letter-spacing: -0.03em;
   text-wrap: balance;
 }

 .landing-page-banner .landing-banner-lead {
   max-width: 660px;
   margin: 18px 0 0;
   color: var(--muted);
   font-size: 17px;
   line-height: 1.7;
   text-wrap: pretty;
 }

 .landing-banner-meta {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 12px;
   margin-top: 22px;
 }

 .landing-banner-meta-item {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   border: 1px solid var(--line);
   border-radius: 9999px;
   background: color-mix(in srgb, var(--surface) 78%, transparent);
   color: var(--text);
   padding: 7px 14px;
   font-size: 12.5px;
   font-weight: 700;
 }

 .landing-banner-meta-item svg {
   color: var(--primary-text);
 }

 .landing-prose {
   max-width: 780px;
   margin: 0 auto;
   color: var(--text);
   font-size: 16px;
   line-height: 1.75;
 }

 .landing-prose h2 {
   margin: 42px 0 14px;
   color: var(--text-strong);
   font-size: 27px;
   font-weight: 800;
   letter-spacing: -0.02em;
 }

 .landing-prose h2:first-child {
   margin-top: 0;
 }

 .landing-prose p,
 .landing-prose li {
   color: var(--text);
 }

 .landing-prose ul {
   padding-left: 4px;
   list-style: none;
 }

 .landing-prose ul li {
   position: relative;
   padding-left: 28px;
   margin: 10px 0;
 }

 .landing-prose ul li::before {
   content: "";
   position: absolute;
   left: 2px;
   top: 9px;
   height: 8px;
   width: 8px;
   border-radius: 9999px;
   background: var(--primary);
   box-shadow: 0 0 0 4px color-mix(in srgb, var(--primary) 16%, transparent);
 }

 .landing-prose strong {
   color: var(--text-strong);
 }

 .landing-prose a {
   color: var(--primary-text);
   font-weight: 700;
 }

 .landing-prose blockquote {
   margin: 26px 0;
   border-left: 3px solid var(--primary);
   border-radius: 0 14px 14px 0;
   background: color-mix(in srgb, var(--primary) 6%, var(--surface));
   padding: 18px 22px;
   color: var(--text);
   font-size: 15.5px;
 }

 /* Check lists (widely reused on content pages) */
 .landing-checklist {
   display: grid;
   grid-template-columns: repeat(2, minmax(0, 1fr));
   gap: 12px;
   margin-top: 6px;
   padding: 0;
   list-style: none;
 }

 .landing-checklist-item {
   display: flex;
   align-items: flex-start;
   gap: 11px;
   border: 1px solid var(--line);
   border-radius: 14px;
   background: var(--surface);
   padding: 14px 16px;
   color: var(--text);
   font-size: 14.5px;
   line-height: 1.5;
   box-shadow: var(--shadow-sm);
 }

 .landing-checklist-item svg {
   flex: none;
   margin-top: 2px;
   color: var(--success);
 }

 /* ============================================================
    How-it-works vertical story
    ============================================================ */
 .landing-how-steps {
   position: relative;
   display: grid;
   gap: 14px;
 }

 .landing-how-steps::before {
   content: "";
   position: absolute;
   left: 25px;
   top: 34px;
   bottom: 34px;
   width: 2px;
   border-radius: 9999px;
   background: linear-gradient(180deg, var(--primary), color-mix(in srgb, var(--primary) 20%, transparent));
   opacity: 0.5;
 }

 .landing-how-step {
   position: relative;
   display: grid;
   grid-template-columns: 52px minmax(0, 1fr);
   gap: 18px;
   align-items: flex-start;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: var(--surface);
   padding: 22px 24px;
   box-shadow: var(--shadow-sm);
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out);
 }

 .landing-how-step:hover {
   transform: translateY(-3px);
   box-shadow: var(--shadow-md);
 }

 .landing-how-num {
   position: relative;
   z-index: 1;
   display: grid;
   height: 52px;
   width: 52px;
   place-items: center;
   border-radius: 16px;
   background: var(--landing-ink-start);
   color: var(--surface);
   font-size: 16px;
   font-weight: 800;
   box-shadow: 0 8px 18px color-mix(in srgb, var(--text-strong) 22%, transparent);
 }

 .landing-how-step h3 {
   margin: 0;
   color: var(--text-strong);
   font-size: 19px;
   font-weight: 800;
   letter-spacing: -0.015em;
 }

 .landing-how-step p {
   margin: 9px 0 0;
   color: var(--muted);
   font-size: 14.5px;
   line-height: 1.65;
 }

 .landing-how-step p strong {
   color: var(--text-strong);
 }

 /* ============================================================
    General grid + card (used on get-started, etc.)
    ============================================================ */
 .landing-grid {
   display: grid;
   grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
   gap: 16px;
 }

 .landing-card {
   display: flex;
   flex-direction: column;
   gap: 12px;
   border: 1px solid var(--line);
   border-radius: var(--landing-radius);
   background: var(--surface);
   padding: 24px;
   box-shadow: var(--shadow-sm);
   text-decoration: none;
   color: inherit;
   transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out), border-color var(--duration-base) var(--ease-out);
 }

 .landing-card[href]:hover {
   transform: translateY(-3px);
   border-color: color-mix(in srgb, var(--primary) 45%, var(--line));
   box-shadow: var(--shadow-md);
 }

 .landing-card-icon {
   display: grid;
   height: 42px;
   width: 42px;
   place-items: center;
   border-radius: 12px;
   background: var(--landing-surface-tint);
   color: var(--primary-text);
 }

 .landing-card-title {
   margin: 0;
   color: var(--text-strong);
   font-size: 18px;
   font-weight: 800;
   letter-spacing: -0.01em;
 }

 .landing-card-body {
   margin: 0;
   color: var(--muted);
   font-size: 14px;
   line-height: 1.6;
 }

 .landing-card-link {
   margin-top: auto;
   color: var(--primary-text);
   font-size: 14px;
   font-weight: 800;
   text-decoration: none;
   display: inline-flex;
   align-items: center;
   gap: 7px;
 }

 .landing-card-link svg {
   transition: transform var(--duration-fast) var(--ease-out);
 }

 .landing-card:hover .landing-card-link svg {
   transform: translateX(3px);
 }

 .landing-card-link:hover {
   text-decoration: underline;
 }

 /* ============================================================
    Footer
    ============================================================ */
 .landing-footer {
   border-top: 1px solid var(--line);
   background: linear-gradient(180deg, var(--canvas) 0%, color-mix(in srgb, var(--primary) 5%, var(--canvas)) 100%);
   padding: clamp(44px, 6vw, 64px) 0 32px;
 }

 .landing-footer-inner {
   width: min(var(--landing-container), 100%);
   margin: 0 auto;
   padding-inline: clamp(20px, 4.5vw, 48px);
 }

 .landing-footer-top {
   display: grid;
   grid-template-columns: 1.4fr 1fr 1fr;
   gap: 32px;
   padding-bottom: 34px;
   border-bottom: 1px solid var(--line);
 }

 .landing-footer-brand {
   max-width: 340px;
 }

 .landing-footer-brand .landing-logo {
   max-width: 150px;
   margin-bottom: 16px;
 }

 .landing-footer-brand p {
   margin: 0;
   color: var(--muted);
   font-size: 14px;
   line-height: 1.65;
 }

 .landing-footer-column h3 {
   margin: 0 0 14px;
   color: var(--text-strong);
   font-size: 13px;
   font-weight: 800;
   letter-spacing: 0.09em;
   text-transform: uppercase;
 }

 .landing-footer-nav {
   display: flex;
   flex-direction: column;
   gap: 10px;
 }

 .landing-footer-link {
   color: var(--text);
   font-size: 14px;
   font-weight: 600;
   text-decoration: none;
   width: fit-content;
   transition: color var(--duration-fast) var(--ease-out);
 }

 .landing-footer-link:hover {
   color: var(--primary-text);
 }

 .landing-footer-bottom {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   justify-content: space-between;
   gap: 14px;
   padding-top: 26px;
 }

 .landing-footer-social {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
 }

 .landing-footer-social-link {
   display: inline-flex;
   align-items: center;
   gap: 6px;
   border: 1px solid var(--line);
   border-radius: 9999px;
   background: var(--surface);
   color: var(--muted);
   padding: 7px 13px;
   font-size: 13px;
   font-weight: 700;
   text-decoration: none;
   transition: border-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out), transform var(--duration-fast) var(--ease-out);
 }

 .landing-footer-social-link:hover {
   border-color: color-mix(in srgb, var(--primary) 45%, var(--line));
   color: var(--primary-text);
   transform: translateY(-2px);
 }

 .landing-footer-social-link svg {
   color: var(--primary-text);
 }

 .landing-footer-copy {
   margin: 0;
   color: var(--muted);
   font-size: 13px;
   text-align: right;
 }

 .landing-footer-copy a {
   color: var(--primary-text);
   text-decoration: none;
 }

 .landing-footer-copy a:hover {
   text-decoration: underline;
 }

 .landing-footer-tagline {
   margin: 12px 0 0;
   color: var(--primary-text);
   font-size: 14px;
   font-weight: 700;
 }

 /* ============================================================
    Responsive
    ============================================================ */
 @media (max-width: 1024px) {
   .landing-stats-grid {
     grid-template-columns: repeat(2, minmax(0, 1fr));
   }
   .landing-trust-grid {
     grid-template-columns: repeat(2, minmax(0, 1fr));
   }
   .landing-process {
     grid-template-columns: repeat(2, minmax(0, 1fr));
   }
   .landing-bento-span-4 { grid-column: span 6; }
   .landing-bento-span-3 { grid-column: span 3; }
   .landing-bento-span-2 { grid-column: span 3; }
 }

 @media (max-width: 760px) {
   .landing-nav-links {
     display: none;
   }
   .landing-nav-cta {
     display: none;
   }
   .landing-nav-toggle {
     display: inline-flex;
   }
   .landing-mobile-menu {
     display: block;
     border-top: 1px solid var(--line);
     background: var(--surface);
   }
   .landing-mobile-menu-inner {
     display: flex;
     flex-direction: column;
     gap: 4px;
     padding: 14px 0 18px;
   }
   .landing-mobile-menu-inner .landing-nav-link {
     padding: 12px 10px;
     border-radius: 12px;
     font-size: 16px;
   }
   .landing-mobile-menu-inner .landing-cta-button {
     margin-top: 10px;
     justify-content: center;
   }
   .landing-preview-body {
     grid-template-columns: 1fr;
   }
   .landing-preview-side {
     display: none;
   }
   .landing-preview-kpis {
     grid-template-columns: 1fr;
   }
   .landing-bento-span-3,
   .landing-bento-span-2 {
     grid-column: span 6;
   }
   .landing-solutions-grid,
   .landing-checklist,
   .landing-compare-head,
   .landing-compare-row {
     grid-template-columns: 1fr;
   }
   .landing-compare-head {
     border-bottom: 1px solid var(--line);
   }
   .landing-compare-row {
     gap: 10px;
   }
   .landing-compare-row .landing-compare-cell + .landing-compare-cell {
     padding-top: 12px;
     border-top: 1px dashed var(--line);
   }
   .landing-footer-top {
     grid-template-columns: 1fr;
     gap: 26px;
   }
   .landing-footer-bottom {
     flex-direction: column;
     align-items: flex-start;
   }
   .landing-footer-copy {
     text-align: left;
   }
   .landing-stats-grid,
   .landing-trust-grid,
   .landing-process {
     grid-template-columns: 1fr;
   }
   .landing-hero-actions .landing-cta-button {
     width: 100%;
   }
 }

 /* ============================================================
    Premium polish v2.2 — typography & interaction refinement.
    Override layer appended after the responsive scale; layout
    widths are intentionally untouched. Token-pure (color-mix).
    ============================================================ */

 /* Base — modern font rendering and refined body copy */
 .landing-header,
 .landing-mobile-menu,
 .landing-main,
 .landing-footer {
   font-family: var(--landing-font-sans);
 }

 .landing-main {
   -webkit-font-smoothing: antialiased;
   text-rendering: optimizeLegibility;
   background:
     radial-gradient(1100px 560px at 78% -12%, var(--landing-surface-tint), transparent 62%),
     radial-gradient(820px 460px at -8% 12%, color-mix(in srgb, var(--accent) 5%, transparent), transparent 55%),
     var(--canvas);
 }

 /* Display type — Space Grotesk for structural headings */
 .landing-hero-title,
 .landing-section-title,
 .landing-page-banner h1,
 .landing-prose h2,
 .landing-card-title,
 .landing-process-step h3,
 .landing-cta-band h2,
 .landing-footer-column h3 {
   font-family: var(--landing-font-display);
   letter-spacing: -0.02em;
   text-wrap: balance;
 }

 .landing-hero-title {
   font-size: clamp(2.05rem, 6.2vw, 3.7rem);
   font-weight: 700;
   line-height: 1.06;
   letter-spacing: -0.028em;
 }

 .landing-hero-title .landing-title-accent {
   background: linear-gradient(105deg, var(--primary-text), var(--primary));
   -webkit-background-clip: text;
   background-clip: text;
   -webkit-text-fill-color: transparent;
   color: transparent;
 }

 .landing-hero-subtitle {
   font-size: clamp(1.02rem, 1.8vw, 1.18rem);
   line-height: 1.7;
   color: color-mix(in srgb, var(--text) 82%, var(--muted));
 }

 .landing-section-title {
   font-size: clamp(1.7rem, 3.5vw, 2.45rem);
   line-height: 1.12;
   color: var(--text-strong);
 }

 .landing-section-kicker {
   font-family: var(--landing-font-mono);
   font-size: 12px;
   font-weight: 500;
   letter-spacing: 0.16em;
 }

 .landing-page-banner h1 {
   font-size: clamp(1.8rem, 4vw, 2.6rem);
   line-height: 1.12;
   letter-spacing: -0.022em;
 }

 .landing-page-banner .landing-banner-lead {
   font-size: 1.08rem;
   line-height: 1.7;
   color: color-mix(in srgb, var(--text) 80%, var(--muted));
 }

 /* Numeric displays — tabular, high-contrast, gradient */
 .landing-stat-value {
   font-family: var(--landing-font-display);
   font-variant-numeric: tabular-nums;
   font-weight: 700;
   font-size: clamp(2.5rem, 5vw, 3.6rem);
   letter-spacing: -0.03em;
   background: linear-gradient(120deg, var(--sidebar-text), color-mix(in srgb, var(--sidebar-text) 58%, var(--primary)));
   -webkit-background-clip: text;
   background-clip: text;
   -webkit-text-fill-color: transparent;
   color: transparent;
 }

 .landing-process-step::before {
   font-family: var(--landing-font-mono);
   font-variant-numeric: tabular-nums;
 }

 /* Controls — crisp geometry, elevated micro-interaction */
 .landing-cta-button,
 .landing-secondary-button {
   border-radius: 12px;
   transition:
     transform 160ms ease,
     box-shadow 160ms ease,
     background-color 160ms ease,
     border-color 160ms ease;
 }

 .landing-cta-button:hover {
   transform: translateY(-2px);
   box-shadow: 0 14px 32px var(--landing-primary-glow);
 }

 .landing-cta-button:active,
 .landing-secondary-button:active {
   transform: translateY(0);
 }

 .landing-secondary-button:hover {
   transform: translateY(-2px);
   border-color: color-mix(in srgb, var(--primary) 42%, var(--line));
 }

 .landing-cta-band .landing-cta-button:hover {
   box-shadow: 0 14px 32px color-mix(in srgb, var(--primary) 42%, transparent);
 }

 /* Navigation — animated indicator */
 .landing-nav-link {
   position: relative;
   transition: color 160ms ease;
 }

 .landing-nav-link::after {
   content: "";
   position: absolute;
   left: 12px;
   right: 12px;
   bottom: 5px;
   height: 2px;
   border-radius: 2px;
   background: var(--primary);
   transform: scaleX(0);
   transform-origin: left center;
   transition: transform 220ms ease;
 }

 .landing-nav-link:hover::after {
   transform: scaleX(1);
 }

 /* Surfaces — hover lift with brand-tinted glow */
 .landing-card,
 .landing-stat-card,
 .landing-process-step {
   transition:
     transform 200ms ease,
     box-shadow 200ms ease,
     border-color 200ms ease;
 }

 .landing-card:hover,
 .landing-stat-card:hover,
 .landing-process-step:hover {
   transform: translateY(-4px);
 }

 .landing-card:hover {
   border-color: color-mix(in srgb, var(--primary) 38%, var(--line));
   box-shadow: 0 20px 44px color-mix(in srgb, var(--accent) 13%, transparent);
 }

 .landing-card:hover .landing-card-title {
   color: var(--primary-text);
 }

 .landing-card-title {
   letter-spacing: -0.015em;
 }

 /* Prose body — legible, deep-navy tint */
 .landing-prose {
   font-size: 1.02rem;
   line-height: 1.78;
   color: color-mix(in srgb, var(--text) 92%, var(--muted));
 }

 .landing-prose blockquote {
   font-family: var(--landing-font-display);
   font-size: clamp(1.12rem, 2vw, 1.3rem);
   letter-spacing: -0.012em;
   line-height: 1.55;
 }

 /* Banner chips & footer brand polish */
 .landing-banner-meta-item {
   background: var(--landing-surface-tint);
 }

 .landing-footer-tagline {
   font-family: var(--landing-font-display);
   letter-spacing: -0.01em;
 }

 /* Keyboard focus — accessible, on-brand */
 .landing-nav-link:focus-visible,
 .landing-nav-toggle:focus-visible,
 .landing-cta-button:focus-visible,
 .landing-secondary-button:focus-visible,
 .landing-card-link:focus-visible,
 .landing-stat-source:focus-visible,
 .landing-footer-link:focus-visible,
 .landing-footer-social-link:focus-visible {
   outline: 2px solid var(--focus-ring);
   outline-offset: 3px;
 }

 /* Reduced motion — respect user preference */
 @media (prefers-reduced-motion: reduce) {
   .landing-hero-orb,
   .landing-hero-tagline::before {
     animation: none;
   }
   .landing-card,
   .landing-stat-card,
   .landing-process-step,
   .landing-cta-button,
   .landing-secondary-button,
   .landing-nav-link,
   .landing-nav-link::after {
     transition: none;
   }
 }

 /* Pricing page */
 .landing-pricing {
   margin-top: 2.2rem;
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 2rem;
 }

 .landing-pricing-switch {
   display: flex;
   gap: 0.375rem;
   padding: 0.25rem;
   border: 1px solid var(--line);
   border-radius: 999px;
   background: var(--surface-muted);
 }

 .landing-pricing-switch button {
   border: 0;
   background: transparent;
   padding: 0.5rem 1.1rem;
   border-radius: 999px;
   font-family: var(--landing-font-mono);
   font-size: 0.8rem;
   font-weight: 700;
   letter-spacing: 0.02em;
   color: var(--muted);
   cursor: pointer;
   transition:
     color 160ms ease,
     background 160ms ease,
     box-shadow 160ms ease;
 }

 .landing-pricing-switch button:hover {
   color: var(--text);
 }

 .landing-pricing-switch button[aria-pressed="true"] {
   color: var(--surface);
   background: var(--primary);
   box-shadow: 0 6px 16px color-mix(in srgb, var(--primary) 40%, transparent);
 }

 .landing-pricing-switch button:focus-visible {
   outline: 2px solid var(--focus-ring);
   outline-offset: 2px;
 }

 .landing-plans-grid {
   display: grid;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
   gap: 1.2rem;
   width: 100%;
   max-width: 1080px;
 }

 .landing-plan-card {
   position: relative;
   display: flex;
   flex-direction: column;
   padding: 1.9rem 1.6rem 1.6rem;
   border: 1px solid var(--line);
   border-radius: var(--radius-md);
   background: var(--surface);
   box-shadow: var(--shadow-sm);
   transition:
     transform 200ms ease,
     box-shadow 200ms ease,
     border-color 200ms ease;
 }

 .landing-plan-card-popular {
   border-color: color-mix(in srgb, var(--primary) 55%, var(--line));
   box-shadow: 0 24px 48px color-mix(in srgb, var(--primary) 22%, transparent);
 }

 .landing-plan-card:hover {
   transform: translateY(-4px);
   border-color: color-mix(in srgb, var(--primary) 42%, var(--line));
   box-shadow: 0 22px 48px color-mix(in srgb, var(--primary) 16%, transparent);
 }

 .landing-plan-badge {
   position: absolute;
   top: -0.7rem;
   left: 50%;
   transform: translateX(-50%);
   padding: 0.3rem 0.9rem;
   border-radius: 999px;
   background: var(--primary);
   color: var(--surface);
   font-family: var(--landing-font-mono);
   font-size: 0.72rem;
   font-weight: 700;
   letter-spacing: 0.04em;
   text-transform: uppercase;
 }

 .landing-plan-name {
   font-family: var(--landing-font-display);
   font-size: 1.5rem;
   font-weight: 700;
   letter-spacing: -0.02em;
   margin: 0;
 }

 .landing-plan-audience {
   margin: 0.35rem 0 0;
   color: var(--muted);
   font-size: 0.92rem;
 }

 .landing-plan-price {
   margin: 1.4rem 0 1.2rem;
   padding-bottom: 1.2rem;
   border-bottom: 1px solid var(--line);
   display: flex;
   align-items: baseline;
   gap: 0.5rem;
 }

 .landing-plan-price-value {
   font-family: var(--landing-font-display);
   font-size: 2.1rem;
   font-weight: 700;
   letter-spacing: -0.03em;
   background: linear-gradient(
     180deg,
     var(--landing-ink-start),
     var(--landing-ink-end)
   );
   -webkit-background-clip: text;
   background-clip: text;
   color: transparent;
 }

 .landing-plan-price-period {
   color: var(--muted);
   font-size: 0.86rem;
 }

 .landing-plan-features {
   list-style: none;
   margin: 0;
   padding: 0;
   display: flex;
   flex-direction: column;
   gap: 0.55rem;
 }

 .landing-plan-features li {
   display: flex;
   align-items: center;
   gap: 0.55rem;
   font-size: 0.95rem;
   line-height: 1.5;
   color: color-mix(in srgb, var(--text) 88%, var(--muted));
 }

 .landing-plan-features svg {
   flex-shrink: 0;
   color: var(--success);
 }

 .landing-plan-cta {
   margin-top: auto;
   width: 100%;
   justify-content: center;
   padding-left: 1rem;
   padding-right: 1rem;
   font-size: 0.95rem;
 }

 .landing-plans-footnote {
   margin: 2rem 0 0;
   max-width: 640px;
   text-align: center;
   color: var(--muted);
   font-size: 0.9rem;
   line-height: 1.6;
 }

 @media (prefers-reduced-motion: reduce) {
   .landing-pricing-switch button,
   .landing-plan-card {
     transition: none;
   }
 }

 /* ============================================================
    Countercheck v2.3 — public landing (2026-09-11)
    Problem/pains, subscriber lifecycle, payment-honesty strip,
-   integrations teaser + pages, product/integrations/security/
+   integrations hub + pages, product/security/customers/
    customers/resources pages. Token variables only.
    ============================================================ */

 /* Hero preview caption */
 .landing-preview-caption {
   margin: 6px auto 0;
   max-width: min(var(--landing-container), 680px);
   text-align: center;
   font-size: 0.82rem;
   color: var(--muted);
 }

 /* Pains grid */
 .landing-problem-grid {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 14px;
   list-style: none;
   margin: 0;
   padding: 0;
 }

 .landing-problem-item {
   padding: 22px 22px 24px;
   border-radius: 18px;
   border: 1px solid var(--line);
   background: var(--surface);
   transition: border-color var(--duration-fast) var(--ease-out),
     transform var(--duration-fast) var(--ease-out);
 }

 .landing-problem-item:hover {
   border-color: color-mix(in srgb, var(--primary) 35%, var(--line));
   transform: translateY(-2px);
 }

 .landing-problem-item h3 {
   margin: 0 0 6px;
   font-size: 1.02rem;
   color: var(--text-strong);
 }

 .landing-problem-item p {
   margin: 0;
   color: var(--muted);
   font-size: 0.93rem;
   line-height: var(--line-height-relaxed);
 }

 /* Payment-honesty strip */
 .landing-honesty {
   display: flex;
   align-items: flex-start;
   gap: 13px;
   margin: 34px auto 34px;
   max-width: 760px;
   padding: 16px 18px;
   border-radius: 16px;
   border: 1px solid color-mix(in srgb, var(--primary) 30%, var(--line));
   background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 6%, var(--canvas)) 0%, var(--canvas) 100%);
 }

 .landing-honesty-icon {
   display: inline-flex;
   flex-shrink: 0;
   width: 36px;
   height: 36px;
   align-items: center;
   justify-content: center;
   border-radius: 11px;
   background: color-mix(in srgb, var(--primary) 14%, transparent);
   color: var(--primary-text);
 }

 .landing-honesty p {
   margin: 0;
   color: var(--text);
   font-size: 0.95rem;
   line-height: var(--line-height-relaxed);
 }

 /* Subscriber lifecycle */
 .landing-lifecycle {
   display: grid;
   grid-template-columns: repeat(auto-fill, minmax(186px, 1fr));
   gap: 14px;
   list-style: none;
   margin: 0;
   padding: 0;
 }

 .landing-lifecycle-step {
   padding: 20px 20px 22px;
   border-radius: 16px;
   border: 1px solid var(--line);
   background: var(--surface);
   transition: border-color var(--duration-fast) var(--ease-out),
     transform var(--duration-fast) var(--ease-out);
 }

 .landing-lifecycle-step:hover {
   border-color: color-mix(in srgb, var(--primary) 35%, var(--line));
   transform: translateY(-2px);
 }

 .landing-lifecycle-num {
   display: inline-flex;
   align-items: center;
   margin-bottom: 10px;
   padding: 2px 9px;
   border-radius: 9999px;
   background: color-mix(in srgb, var(--primary) 12%, transparent);
   color: var(--primary-text);
   font-family: var(--landing-font-display);
   font-size: 0.78rem;
   font-weight: 700;
   letter-spacing: 0.06em;
 }

 .landing-lifecycle-step h3 {
   margin: 0 0 6px;
   font-size: 0.98rem;
   color: var(--text-strong);
 }

 .landing-lifecycle-step p {
   margin: 0;
   color: var(--muted);
   font-size: 0.88rem;
   line-height: var(--line-height-relaxed);
 }

 /* Status chips */
 .landing-status-chip {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 3px 10px;
   border-radius: 9999px;
   border: 1px solid transparent;
   font-size: 0.78rem;
   font-weight: 650;
   line-height: 1.4;
   white-space: nowrap;
 }

 .landing-status-chip::before {
   content: "";
   width: 7px;
   height: 7px;
   border-radius: 50%;
   background: currentColor;
 }

 .landing-status-available {
   color: color-mix(in srgb, var(--success) 85%, var(--text));
   background: color-mix(in srgb, var(--success) 11%, transparent);
   border-color: color-mix(in srgb, var(--success) 30%, transparent);
 }

 .landing-status-beta {
   color: color-mix(in srgb, var(--primary) 85%, var(--text));
   background: color-mix(in srgb, var(--primary) 12%, transparent);
   border-color: color-mix(in srgb, var(--primary) 32%, transparent);
 }

 .landing-status-planned {
   color: color-mix(in srgb, var(--text) 46%, var(--muted));
   background: color-mix(in srgb, var(--text) 6%, transparent);
   border-color: color-mix(in srgb, var(--text) 14%, transparent);
 }

 .landing-status-custom {
   color: color-mix(in srgb, var(--warning) 80%, var(--text));
   background: color-mix(in srgb, var(--warning) 12%, transparent);
   border-color: color-mix(in srgb, var(--warning) 32%, transparent);
 }

 /* Legend rows */
 .landing-legend {
   display: flex;
   flex-wrap: wrap;
   gap: 10px 22px;
   margin: 0 auto;
   max-width: 720px;
   justify-content: center;
 }

 .landing-legend-item {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   font-size: 0.88rem;
   color: var(--muted);
 }

 .landing-legend-note {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   font-size: 0.84rem;
   color: var(--muted);
 }

 /* Integrations page */
 .landing-int-groups {
   display: grid;
   gap: 34px;
   margin-top: 46px;
 }

 .landing-int-group h2 {
   margin: 0 0 4px;
   font-size: 1.35rem;
   color: var(--text-strong);
 }

 .landing-int-group-desc {
   margin: 0 0 18px;
   color: var(--muted);
   font-size: 0.95rem;
 }

 .landing-int-list {
   list-style: none;
   margin: 0;
   padding: 0;
   border: 1px solid var(--line);
   border-radius: 18px;
   overflow: hidden;
   background: var(--surface);
 }

 .landing-int-row {
   display: grid;
   grid-template-columns: minmax(190px, 1fr) auto minmax(220px, 2.2fr);
   gap: 14px 22px;
   align-items: baseline;
   padding: 16px 20px;
   border-bottom: 1px solid var(--line);
 }

 .landing-int-row:last-child {
   border-bottom: 0;
 }

 .landing-int-name {
   color: var(--text-strong);
   font-weight: 600;
   font-size: 0.95rem;
 }

 .landing-int-note {
   color: var(--muted);
   font-size: 0.89rem;
   line-height: var(--line-height-relaxed);
 }

 /* Integrations teaser tiles (home) */
 .landing-int-tiles {
   display: grid;
   grid-template-columns: repeat(auto-fit, minmax(158px, 1fr));
