       payeeId: args.payeeId,
       marketId: args.marketId,
       amountLocal: args.amountLocal,
       currency: args.currency,
       amountUSD,
       method: args.method,
       status: "pending_approval",
       approvalTier: tierForAmountUsd(amountUSD),
       requestedBy: user._id,
       requestedAt: Date.now(),
       notes: args.notes,
     });
     await logAudit(ctx, {
