import { NextResponse, type NextFetchEvent, type NextRequest } from "next/server";

const authProxy = authkitMiddleware({
  middlewareAuth: {
    enabled: true,
    unauthenticatedPaths: [
      "/signin",
      "/auth/callback",
      "/",
      "/features",
      "/solutions",
      "/product",
      "/product/integrations",
      "/security",
      "/customers",
      "/resources",
