      "/solutions/market-hotspots",
      "/solutions/estate-networks",
      "/solutions/hospitality",
      "/solutions/community-networks",
      "/pricing",
      "/get-started",
      "/contact",
      "/resources/how-it-works",
      "/resources/billing-and-payments",
      "/resources/kenya-payment-automation",
      "/resources/mikrotik-radius-operations",
      "/resources/captive-portal-hotspot-guide",
      "/resources/wisp-launch-playbook",
      "/resources/estate-network-playbook",
      "/resources/subscriber-migration-checklist",
      "/resources/isp-kpi-primer",
      "/company/about",
      "/legal/privacy",
      "/legal/terms",
      "/landing",
      "/landing/get-started",
    ],
  },
});

export default async function proxy(request: NextRequest, event: NextFetchEvent) {
  const password = process.env.WORKOS_COOKIE_PASSWORD;
  if (!password || password.length < 32) {
    return new NextResponse("Service configuration is incomplete.", { status: 503 });
  }
  try {
    return await authProxy(request, event);
  } catch {
    return new NextResponse("Authentication is temporarily unavailable.", { status: 503 });
  }
}

export const config = {
  matcher: [
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|xml|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|txt|zip|webmanifest)).*)",
    "/(api|trpc)(.*)",
  ],
};

