/**
 * Cookie policy for the MylesNet web app.
 *
 * Implements the Cookie Handling standard: cookie names are `__mylesnet_*`,
 * every cookie sets httpOnly+secure+sameSite+path+maxAge, clears are done by
 * writing an empty value with maxAge 0 / expires epoch (never `delete()` alone),
 * and only the CSRF cookie is readable by client-side JavaScript — which the
 * double-submit flow explicitly requires and documents here.
 */

const PRODUCT_PREFIX = "mylesnet";

export const TENANT_COOKIE_NAME = `__${PRODUCT_PREFIX}_tenant`;
export const CSRF_COOKIE_NAME = `__${PRODUCT_PREFIX}_csrf`;

export const TENANT_COOKIE_MAX_AGE = 60 * 60 * 24 * 30; // 30 days (session-bound)
export const CSRF_COOKIE_MAX_AGE = 60 * 60 * 24 * 30;

export interface MylesnetCookieOptions {
  httpOnly: boolean;
  secure: boolean;
  sameSite: "lax" | "strict";
  path: string;
  maxAge: number;
  domain: string | undefined;
  expires?: Date;
}

/**
 * Base options every MylesNet cookie must carry. `secure` stays true even in
 * development per the Cookie Handling standard. Domain defaults to the
 * `MYLESNET_COOKIE_DOMAIN` env (set to the product apex, e.g. `.mylesnet.com`,
 * once the production domain is approved) so panel/tenant subdomains share it.
 */
export function baseCookieOptions(
  overrides: Partial<MylesnetCookieOptions> = {},
): MylesnetCookieOptions {
  return {
    httpOnly: true,
    secure: true,
    sameSite: "lax",
    path: "/",
    maxAge: TENANT_COOKIE_MAX_AGE,
    domain: process.env.MYLESNET_COOKIE_DOMAIN ?? undefined,
    ...overrides,
  };
}

/**
 * CSRF cookie options. httpOnly is intentionally false: the double-submit
 * scheme requires the client to read the token and echo it in a header, so
 * this cookie is the documented exception to the httpOnly rule (Cookie
 * Handling: "never without httpOnly unless client-side JavaScript access is
 * explicitly required and documented in a code comment").
 */
export function csrfCookieOptions(): MylesnetCookieOptions {
  return baseCookieOptions({ httpOnly: false, maxAge: CSRF_COOKIE_MAX_AGE });
}

/**
 * Options for clearing a cookie. Clearing sets an empty value with maxAge 0
 * and expires epoch instead of calling `response.cookies.delete()` alone.
 */
export function clearCookieOptions(base: MylesnetCookieOptions): MylesnetCookieOptions {
  return {
    ...base,
    httpOnly: base.httpOnly,
    maxAge: 0,
    expires: new Date(0),
  };
}

/**
 * CSRF protection core (pure, node/browser-safe).
 *
 * Implements the CSRF Protection standard for MylesNet's double-submit scheme:
 * one token per session stored in the `__mylesnet_csrf` cookie (httpOnly=false
 * by design, see cookies.ts), echoed back in the `X-CSRF-Token` header on every
 * state-changing request, verified server-side before any mutation, and rotated
 * after every successful use.
 *
 * These functions are pure so they can be unit-tested with `node --test`.
 * Route handlers and server actions compose them with the cookie/header readers
 * in `cookies.ts` and `session.ts`.
 */

export const CSRF_TOKEN_BYTES = 32;
export const CSRF_HEADER_NAME = "X-CSRF-Token";

/** URL-safe base64 alphabet, no padding. */
export function toBase64Url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary)
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}

/** Generate a new cryptographically random CSRF token (32 random bytes). */
export function generateCsrfToken(): string {
  const bytes = new Uint8Array(CSRF_TOKEN_BYTES);
  crypto.getRandomValues(bytes);
  return toBase64Url(bytes);
}

/** True when the value looks like a token we generated (length + alphabet). */
export function isWellFormedCsrfToken(value: string | undefined | null): boolean {
  if (typeof value !== "string" || value.length < 16 || value.length > 128) return false;
  return /^[A-Za-z0-9_-]+$/.test(value);
}

/** Constant-time string comparison. Never throws on length mismatch. */
export function timingSafeEqualString(a: string | undefined, b: string | undefined): boolean {
  if (typeof a !== "string" || typeof b !== "string") return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

/**
 * Verify a double-submit CSRF exchange. The cookie token and header token must
 * be present, well-formed, of equal length and compare constant-time equal.
 * Returns false (never throws) on any mismatch so callers can fail closed.
 */
export function verifyCsrfToken(
  cookieToken: string | undefined | null,
  headerToken: string | undefined | null,
): boolean {
  if (!isWellFormedCsrfToken(cookieToken) || !isWellFormedCsrfToken(headerToken)) {
    return false;
  }
  return timingSafeEqualString(cookieToken, headerToken);
}

/**
 * Tenant resolution from the request hostname (pure, node/browser-safe).
 *
 * Implements the DNS + panel-hostname plan: tenant panels live at
 * `[tenant].<domain>` while `/platform`, `/admin`, `/dashboard`, `/reseller`,
 * `/agency` and `/partner` panel hosts are `admin|network|dashboard|reseller|
 * agency|partner.<domain>`. The proxy uses these helpers to set the
 * `__mylesnet_tenant` cookie; the Convex layer re-derives the authoritative
 * tenant from WorkOS org membership, never from the URL alone.
 */

import { TENANT_COOKIE_NAME, TENANT_COOKIE_MAX_AGE, baseCookieOptions } from "./cookies";

export const BOOTSTRAP_TENANT_SLUG = "mylesnet";

/** Reserved panel subdomains (canonical panel map, 99-mylesnet-orientation). */
export const PANEL_SUBDOMAINS = [
  "admin",
  "network",
  "dashboard",
  "reseller",
  "agency",
  "partner",
] as const;

export type PanelSubdomain = (typeof PANEL_SUBDOMAINS)[number];

export const PANEL_SUBDOMAIN_SET: ReadonlySet<string> = new Set<string>(PANEL_SUBDOMAINS);

/** Tenant slug shape: 2-63 lowercase alphanumerics with optional single hyphens. */
export const TENANT_SLUG_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

export function isValidTenantSlug(slug: string | undefined | null): slug is string {
  return typeof slug === "string" && slug.length >= 2 && slug.length <= 63 && TENANT_SLUG_RE.test(slug);
}

/**
 * Normalize a Host header/URL to a lowercase hostname without protocol, port
 * or a leading `www.` (e.g. `https://Admin.mylesnet.com:3000` -> `admin.mylesnet.com`).
 */
export function normalizeHost(host: string | undefined | null): string {
  if (!host) return "";
  let value = host.replace(/^[a-z]+:\/\//i, "").split(/[/?#]/, 1)[0] ?? "";
  value = value.split(":", 1)[0] ?? "";
  value = value.toLowerCase();
  if (value.startsWith("www.")) value = value.slice(4);
  return value;
}

/** True when the host is a reserved panel host (`panel.<domain>`). */
export function isPanelHost(host: string | undefined | null): boolean {
  const normalized = normalizeHost(host);
  if (!normalized) return false;
  const [label] = normalized.split(".");
  return label !== undefined && PANEL_SUBDOMAIN_SET.has(label);
}

/** True when the host has no tenant subdomain (apex, `localhost`, bare IP). */
export function isApexHost(host: string | undefined | null): boolean {
  const normalized = normalizeHost(host);
  if (!normalized) return false;
  const labels = normalized.split(".");
  const first = labels[0] ?? "";
  return labels.length === 1 || PANEL_SUBDOMAIN_SET.has(first);
}

/**
 * Resolve the tenant slug from a hostname. Returns null when there is no
 * tenant subdomain (panel host, apex, `localhost`, bare IP) — callers fall
 * back to the bootstrap slug (`mylesnet`) for the pre-migration dashboard.
 */
export function tenantSlugFromHost(host: string | undefined | null): string | null {
  const normalized = normalizeHost(host);
  if (!normalized) return null;
  const [label] = normalized.split(".");
  if (label === undefined) return null;
  if (PANEL_SUBDOMAIN_SET.has(label)) return null;
  if (!isValidTenantSlug(label)) return null;
  return label;
}

/** Cookie name + matching options for the tenant cookie set by the proxy. */
export function tenantCookieDef() {
  return {
    name: TENANT_COOKIE_NAME,
    options: baseCookieOptions({ httpOnly: true, maxAge: TENANT_COOKIE_MAX_AGE }),
  };
}

/**
 * RBAC helpers for the web layer (pure, node/browser-safe).
 *
 * These helpers are optimistic UI-side checks on the WorkOS access-token
 * claims (`roles`, `permissions`). The authoritative checks stay in Convex
 * (`convex/lib/auth.ts`, `convex/lib/permissions.ts`) — never gate a mutation
 * on these alone.
 */
import { SYSTEM_ROLE_SLUGS } from "@/convex/lib/permissions";

/** Panel names (canonical map, 99-mylesnet-orientation). */
export type PanelName = "platform" | "network" | "dashboard" | "reseller" | "agency" | "partner";

/**
 * Role-slug prefix -> panel(s). `agent` currently maps the pre-migration
 * single-dashboard estate; multi-panel roles land with Phase 2/5-6.
 */
export const PANEL_ROLE_PREFIXES: Record<PanelName, string[]> = {
  platform: ["platform"],
  network: ["network", "super_admin", "admin_ops"],
  dashboard: ["agent", "dashboard", "tenant", "sales"],
  reseller: ["reseller"],
  agency: ["agency"],
  partner: ["partner"],
};

const PANEL_PREFIX_LOOKUP: ReadonlyMap<string, PanelName> = new Map(
  (Object.entries(PANEL_ROLE_PREFIXES) as Array<[PanelName, string[]]>).flatMap(
    ([panel, prefixes]) => prefixes.map((prefix) => [prefix, panel]),
  ),
);

/** Panel name whose role prefixes include the given role slug, if any. */
export function panelForRole(roleSlug: string): PanelName | null {
  for (const prefix of PANEL_PREFIX_LOOKUP.keys()) {
    if (roleSlug === prefix || roleSlug.startsWith(`${prefix}_`) || roleSlug.startsWith(`${prefix}:`)) {
      return PANEL_PREFIX_LOOKUP.get(prefix) ?? null;
    }
  }
  return null;
}

/** True when any held role maps to the given panel. */
export function roleMatchesPanel(roleSlugs: string[], panel: PanelName): boolean {
  return roleSlugs.some((slug) => panelForRole(slug) === panel);
}

/** True when the user holds every required role. */
export function hasRole(roleSlugs: string[], requiredRoles: string[]): boolean {
  if (requiredRoles.length === 0) return true;
  return requiredRoles.every((role) => roleSlugs.includes(role));
}

/** True when the user holds at least one of the required roles. */
export function hasAnyRole(roleSlugs: string[], requiredRoles: string[]): boolean {
  if (requiredRoles.length === 0) return true;
  return requiredRoles.some((role) => roleSlugs.includes(role));
}

/** True when every required permission is present in the token claims. */
export function hasPermission(permissions: string[], requiredPermissions: string[]): boolean {
  if (requiredPermissions.length === 0) return true;
  return requiredPermissions.every((permission) => permissions.includes(permission));
}

/** True when at least one required permission is present. */
export function hasAnyPermission(permissions: string[], requiredPermissions: string[]): boolean {
  if (requiredPermissions.length === 0) return true;
  return requiredPermissions.some((permission) => permissions.includes(permission));
}

/** Flatten a WorkOS `roles`/`permissions` claim (array of strings) to string[]. */
export function toClaimArray(value: unknown): string[] {
  if (Array.isArray(value)) return value.filter((entry): entry is string => typeof entry === "string");
  if (typeof value === "string") return [value];
  return [];
}

/** Flatten org-scoped role claims shaped `{ [orgId]: string[] }` into one list. */
export function flattenOrgScopedRoles(value: unknown): string[] {
  if (typeof value === "object" && value !== null) {
    return Object.values(value as Record<string, unknown>).flatMap(toClaimArray);
  }
  return toClaimArray(value);
}

/** True when any held role is a platform staff role (platform_*). */
export function isPlatformStaff(roleSlugs: string[]): boolean {
  return roleSlugs.some((slug) => slug === "platform" || slug.startsWith("platform_") || slug.startsWith("platform:"));
}

/** The system role slugs catalog (from convex). Re-exported for UI wiring. */
export { SYSTEM_ROLE_SLUGS };

/**
 * Server-side session facade for MylesNet.
 *
 * Builds on AuthKit's `getTokenClaims` (workforce identity) and the
 * `__mylesnet_*` cookie policy. This is the optimistic/server data layer: the
 * Convex guards in `convex/lib/auth.ts` remain the authority for any mutation.
 * All functions are async to match Next.js 16's async `cookies()`/authkit APIs.
 */

import { getTokenClaims } from "@workos-inc/authkit-nextjs";
import { cookies } from "next/headers";
import { TENANT_COOKIE_NAME, TENANT_COOKIE_MAX_AGE, baseCookieOptions } from "./cookies";
import { hasAnyRole, toClaimArray } from "./rbac";
import { BOOTSTRAP_TENANT_SLUG } from "./tenant";

export class AuthRequiredError extends Error {
  readonly status = 401;
  constructor(message = "Authentication required.") {
    super(message);
    this.name = "AuthRequiredError";
  }
}

export class RoleRequiredError extends Error {
  readonly status = 403;
  constructor(roles: string[]) {
    super(`Unauthorized: one of role(s) ${roles.join(", ")} required.`);
    this.name = "RoleRequiredError";
  }
}

export interface AuthSession {
  workosUserId: string;
  email?: string;
  orgId?: string;
  roleSlugs: string[];
  permissions: string[];
  authenticatedAt?: Date;
}

/** Read and decode the current AuthKit token claims into a typed session. */
export async function getSession(): Promise<AuthSession | null> {
  try {
    const claims = await getTokenClaims();
    if (!claims?.sub) return null;
    return {
      workosUserId: claims.sub,
      email: typeof claims.email === "string" ? claims.email : undefined,
      orgId: typeof claims.org_id === "string" ? claims.org_id : undefined,
      roleSlugs: toClaimArray(claims.roles),
      permissions: toClaimArray(claims.permissions),
      authenticatedAt:
        typeof claims.auth_time === "number" ? new Date(claims.auth_time * 1000) : undefined,
    };
  } catch {
    return null;
  }
}

/** Return the session or throw AuthRequiredError (route handlers / actions). */
export async function requireUser(): Promise<AuthSession> {
  const session = await getSession();
  if (!session) throw new AuthRequiredError();
  return session;
}

/** Return the session only when the user holds at least one required role. */
export async function requireRole(requiredRoles: string[]): Promise<AuthSession> {
  const session = await requireUser();
  if (!hasAnyRole(session.roleSlugs, requiredRoles)) {
    throw new RoleRequiredError(requiredRoles);
  }
  return session;
}

/**
 * Resolve the active tenant slug for the request.
 *
 * Reads the `__mylesnet_tenant` cookie set by the proxy from the hostname.
 * Falls back to the bootstrap slug while single-hostname operating (pre-
 * multi-panel); Convex re-derives the authoritative tenant from WorkOS org
 * membership.
 */
export async function getActiveTenantSlug(): Promise<string> {
  const cookieStore = await cookies();
  const stored = cookieStore.get(TENANT_COOKIE_NAME)?.value;
  if (stored) return stored;
  return BOOTSTRAP_TENANT_SLUG;
}

/** Persist the tenant cookie (used by the proxy; opt-in callers). */
export async function setTenantCookie(slug: string): Promise<void> {
  const cookieStore = await cookies();
  cookieStore.set(TENANT_COOKIE_NAME, slug, baseCookieOptions({ httpOnly: true, maxAge: TENANT_COOKIE_MAX_AGE }));
}

/** Names of every MylesNet-owned cookie cleared on sign-out/expiry. */
export function mylesnetCookieNames(): string[] {
  return [TENANT_COOKIE_NAME];
}

