import { test } from "node:test";
import assert from "node:assert/strict";
import {
  CSRF_HEADER_NAME,
  generateCsrfToken,
  isWellFormedCsrfToken,
  timingSafeEqualString,
  toBase64Url,
  verifyCsrfToken,
} from "./csrf.ts";

test("generateCsrfToken produces distinct, well-formed URL-safe tokens", () => {
  const a = generateCsrfToken();
  const b = generateCsrfToken();
  assert.notEqual(a, b);
  assert.ok(isWellFormedCsrfToken(a));
  assert.ok(isWellFormedCsrfToken(b));
  assert.ok(a.length >= 32);
  assert.doesNotMatch(a, /[+/=]/);
});

test("toBase64Url is deterministic and URL-safe", () => {
  const bytes = new Uint8Array([0xff, 0x00, 0x3d, 0xfb]);
  assert.equal(toBase64Url(bytes), "___9-"); // 255,0,61,251 -> "_-8D-..." padded variant
  const empty = new Uint8Array(0);
  assert.equal(toBase64Url(empty), "");
});

test("isWellFormedCsrfToken rejects malformed values", () => {
  assert.equal(isWellFormedCsrfToken(undefined), false);
  assert.equal(isWellFormedCsrfToken(null), false);
  assert.equal(isWellFormedCsrfToken(""), false);
  assert.equal(isWellFormedCsrfToken("short"), false);
  assert.equal(isWellFormedCsrfToken("a".repeat(200)), false);
  assert.equal(isWellFormedCsrfToken("bad+token!"), false);
});

test("timingSafeEqualString compares constant-time and never throws", () => {
  assert.equal(timingSafeEqualString("abc", "abc"), true);
  assert.equal(timingSafeEqualString("abc", "abd"), false);
  assert.equal(timingSafeEqualString("abc", "abcd"), false);
  assert.equal(timingSafeEqualString(undefined, undefined), false);
  assert.equal(timingSafeEqualString("abc", null as unknown as string), false);
});

test("verifyCsrfToken requires a matching cookie + header pair", () => {
  const token = generateCsrfToken();
  assert.equal(verifyCsrfToken(token, token), true);
  assert.equal(verifyCsrfToken(token, generateCsrfToken()), false);
  assert.equal(verifyCsrfToken(token, undefined), false);
  assert.equal(verifyCsrfToken(undefined, token), false);
  assert.equal(verifyCsrfToken("", ""), false);
  assert.equal(verifyCsrfToken(undefined, undefined), false);
});

test("CSRF_HEADER_NAME matches the convention used by clients", () => {
  assert.equal(CSRF_HEADER_NAME, "X-CSRF-Token");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  BOOTSTRAP_TENANT_SLUG,
  PANEL_SUBDOMAINS,
  isApexHost,
  isPanelHost,
  isValidTenantSlug,
  normalizeHost,
  tenantSlugFromHost,
} from "./tenant.ts";

test("normalizeHost strips protocol, port, path and leading www", () => {
  assert.equal(normalizeHost("https://Admin.mylesnet.com:3000"), "admin.mylesnet.com");
  assert.equal(normalizeHost("http://cloud.example.com/a?b=1"), "cloud.example.com");
  assert.equal(normalizeHost("tenant.mylesnet.com:8443"), "tenant.mylesnet.com");
  assert.equal(normalizeHost("www.tenant.mylesnet.com"), "tenant.mylesnet.com");
  assert.equal(normalizeHost("localhost"), "localhost");
  assert.equal(normalizeHost(""), "");
  assert.equal(normalizeHost(undefined), "");
});

test("PANEL_SUBDOMAINS covers the canonical panel map", () => {
  assert.deepEqual([...PANEL_SUBDOMAINS], ["admin", "network", "dashboard", "reseller", "agency", "partner"]);
});

test("isPanelHost recognizes reserved panel hosts", () => {
  assert.equal(isPanelHost("admin.mylesnet.com"), true);
  assert.equal(isPanelHost("network.mylesnet.com"), true);
  assert.equal(isPanelHost("dashboard.mylesnet.com"), true);
  assert.equal(isPanelHost("foo.mylesnet.com"), false);
  assert.equal(isPanelHost("localhost"), false);
  assert.equal(isPanelHost("mylesnet.com"), false);
});

test("isApexHost recognizes apex, localhost and bare hosts", () => {
  assert.equal(isApexHost("mylesnet.com"), true);
  assert.equal(isApexHost("localhost"), true);
  assert.equal(isApexHost("127.0.0.1"), true);
  assert.equal(isApexHost("admin.mylesnet.com"), true); // panel host has no tenant
  assert.equal(isApexHost("tenant.mylesnet.com"), false);
});

test("isValidTenantSlug enforces slug shape", () => {
  assert.equal(isValidTenantSlug("safaricom"), true);
  assert.equal(isValidTenantSlug("mount-kenya-isp"), true);
  assert.equal(isValidTenantSlug("a1"), true);
  assert.equal(isValidTenantSlug("a b"), false);
  assert.equal(isValidTenantSlug("UPPER"), false);
  assert.equal(isValidTenantSlug("a"), false);
  assert.equal(isValidTenantSlug("x".repeat(64)), false);
  assert.equal(isValidTenantSlug(""), false);
  assert.equal(isValidTenantSlug(undefined), false);
});

test("tenantSlugFromHost resolves the tenant subdomain", () => {
  assert.equal(tenantSlugFromHost("safaricom.mylesnet.com"), "safaricom");
  assert.equal(tenantSlugFromHost("Mount-Kenya.mylesnet.com:3000"), "mount-kenya");
  assert.equal(tenantSlugFromHost("admin.mylesnet.com"), null);
  assert.equal(tenantSlugFromHost("mylesnet.com"), null);
  assert.equal(tenantSlugFromHost("localhost"), null);
  assert.equal(tenantSlugFromHost(""), null);
});

test("BOOTSTRAP_TENANT_SLUG matches the convex bootstrap fallback", () => {
  assert.equal(BOOTSTRAP_TENANT_SLUG, "mylesnet");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  flattenOrgScopedRoles,
  hasAnyPermission,
  hasAnyRole,
  hasPermission,
  hasRole,
  isPlatformStaff,
  panelForRole,
  roleMatchesPanel,
  toClaimArray,
} from "./rbac.ts";

test("panelForRole maps role slugs to canonical panels", () => {
  assert.equal(panelForRole("platform_owner"), "platform");
  assert.equal(panelForRole("platform_admin"), "platform");
  assert.equal(panelForRole("network_operator"), "network");
  assert.equal(panelForRole("agent"), "dashboard");
  assert.equal(panelForRole("reseller_manager"), "reseller");
  assert.equal(panelForRole("agency_admin"), "agency");
  assert.equal(panelForRole("partner_ops"), "partner");
  assert.equal(panelForRole("unknown_role"), null);
});

test("roleMatchesPanel is true when any held role maps to the panel", () => {
  assert.equal(roleMatchesPanel(["agent", "network_operator"], "network"), true);
  assert.equal(roleMatchesPanel(["agent"], "dashboard"), true);
  assert.equal(roleMatchesPanel(["agent"], "network"), false);
});

test("hasRole / hasAnyRole implement all-vs-any semantics", () => {
  assert.equal(hasRole(["platform_owner", "platform_admin"], ["platform_admin"]), true);
  assert.equal(hasRole(["platform_owner"], ["platform_admin"]), false);
  assert.equal(hasRole(["platform_owner"], []), true);
  assert.equal(hasAnyRole(["agent"], ["platform_owner", "agent"]), true);
  assert.equal(hasAnyRole(["agent"], ["platform_owner"]), false);
  assert.equal(hasAnyRole(["agent"], []), true);
});

test("hasPermission / hasAnyPermission implement all-vs-any semantics", () => {
  assert.equal(hasPermission(["dashboard:access", "routers:read"], ["dashboard:access", "routers:read"]), true);
  assert.equal(hasPermission(["dashboard:access"], ["dashboard:access", "routers:read"]), false);
  assert.equal(hasPermission(["dashboard:access"], []), true);
  assert.equal(hasAnyPermission(["routers:read"], ["dashboard:access", "routers:read"]), true);
  assert.equal(hasAnyPermission(["other"], ["dashboard:access"]), false);
});

test("toClaimArray normalizes single values and arrays", () => {
  assert.deepEqual(toClaimArray("platform_owner"), ["platform_owner"]);
  assert.deepEqual(toClaimArray(["a", "b"]), ["a", "b"]);
  assert.deepEqual(toClaimArray(["a", 1, null, "b"]), ["a", "b"]);
  assert.deepEqual(toClaimArray(undefined), []);
  assert.deepEqual(toClaimArray(null), []);
  assert.deepEqual(toClaimArray({} as unknown), []);
});

test("flattenOrgScopedRoles handles org-scoped role claims", () => {
  assert.deepEqual(flattenOrgScopedRoles({ org_1: ["plat_owner"] }), ["plat_owner"]);
  assert.deepEqual(flattenOrgScopedRoles({ org_1: ["a", "b"], org_2: ["c"] }), ["a", "b", "c"]);
  assert.deepEqual(flattenOrgScopedRoles(["flat"]), ["flat"]);
  assert.deepEqual(flattenOrgScopedRoles(undefined), []);
});

test("isPlatformStaff flags platform staff roles", () => {
  assert.equal(isPlatformStaff(["platform_owner"]), true);
  assert.equal(isPlatformStaff(["platform_admin", "agent"]), true);
  assert.equal(isPlatformStaff(["agent"]), false);
  assert.equal(isPlatformStaff([]), false);
});

