import { authkitMiddleware } from "@workos-inc/authkit-nextjs";
import { NextResponse, type NextFetchEvent, type NextRequest } from "next/server";
import { TENANT_COOKIE_NAME, TENANT_COOKIE_MAX_AGE, baseCookieOptions } from "@/lib/auth/cookies";
import { tenantSlugFromHost } from "@/lib/auth/tenant";

const authProxy = authkitMiddleware({
  middlewareAuth: {
    enabled: true,
    unauthenticatedPaths: [
      "/signin",
      "/auth/callback",
      "/",
      "/features",
      "/solutions",
      "/product",
      "/product/integrations",
      "/security",
      "/customers",
      "/resources",
      "/features/customer-management",
      "/features/packages-vouchers",
      "/features/payments-finance",
      "/features/network-operations",
      "/features/support-communications",
      "/solutions/market-hotspots",
      "/solutions/estate-networks",
      "/solutions/hospitality",
      "/solutions/community-networks",
      "/pricing",
      "/get-started",
      "/contact",
      "/resources/how-it-works",
      "/resources/billing-and-payments",
      "/resources/kenya-payment-automation",
      "/resources/mikrotik-radius-operations",
      "/resources/captive-portal-hotspot-guide",
      "/resources/wisp-launch-playbook",
      "/resources/estate-network-playbook",
      "/resources/subscriber-migration-checklist",
      "/resources/isp-kpi-primer",
      "/company/about",
      "/legal/privacy",
      "/legal/terms",
      "/landing",
      "/landing/get-started",
    ],
  },
});

/** Opaque, additive security headers (Security Standards; CSP deferred). */
function applySecurityHeaders(response: NextResponse): void {
  response.headers.set("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
  response.headers.set("X-Content-Type-Options", "nosniff");
  response.headers.set("X-Frame-Options", "SAMEORIGIN");
  response.headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  response.headers.set(
    "Permissions-Policy",
    "camera=(), microphone=(), geolocation=(self), payment=(self)",
  );
}

/** Set the tenant cookie from the request hostname (Cookie Handling). */
function applyTenantCookie(request: NextRequest, response: NextResponse): void {
  const slug = tenantSlugFromHost(request.nextUrl.hostname);
  if (!slug) return;
  if (request.cookies.get(TENANT_COOKIE_NAME)?.value === slug) return;
  response.cookies.set(
    TENANT_COOKIE_NAME,
    slug,
    baseCookieOptions({ httpOnly: true, maxAge: TENANT_COOKIE_MAX_AGE }),
  );
}

export default async function proxy(request: NextRequest, event: NextFetchEvent) {
  const password = process.env.WORKOS_COOKIE_PASSWORD;
  if (!password || password.length < 32) {
    return new NextResponse("Service configuration is incomplete.", { status: 503 });
  }
  try {
    const response = await authProxy(request, event);
    applySecurityHeaders(response);
    applyTenantCookie(request, response);
    return response;
  } catch {
    return new NextResponse("Authentication is temporarily unavailable.", { status: 503 });
  }
}

